						}</v></c>`
					}
					strSheetXml += '</row>'
				})
			} else {
				// strSheetXml += '<cols><col min="1" max="1" width="11" customWidth="1" /></cols>'
				strSheetXml += '<sheetData>'

				/* EX: INPUT: `data`
					[
						{ name:'Red', labels:['Jan..May-17'], values:[11,13,14,15,16] },
						{ name:'Amb', labels:['Jan..May-17'], values:[22, 6, 7, 8, 9] },
