    case "school_gap_then_higher":
      return `El estudiante sale de la observacion escolar y reaparece en superior tras un gap de ${gapToHigherYears} anio(s).`;
    case "school_only":
      return "La trayectoria queda observada solo en escolar; no aparece un match posterior en superior dentro de la base publica.";
    case "higher_only":
      return "El estudiante entra directo por la capa de superior; no existe un tramo escolar canonico previo en esta base.";
    case "school_and_higher":
      return "El estudiante aparece en ambos dominios, pero la secuencia no cae en una transicion escolar -> superior limpia.";
    default:
      return "La trayectoria fue resuelta, pero la secuencia aun no cae en una tipologia fuerte.";
  }
}

function schoolStageMeta(educationCode: string, gradeCode: string, ensCode: string) {
  return [educationCode ? `Cod ${educationCode}` : "", gradeCode ? `Grado ${gradeCode}` : "", ensCode ? `ENS ${ensCode}` : ""]
    .filter(Boolean)
    .join(" · ");
}

function schoolContextMeta(rbd: string, dependencyGroupCode: string, slepName: string, communeCode: string) {
  return [
    rbd ? `RBD ${rbd}` : "",
    dependencyGroupCode ? `Dep ${dependencyGroupCode}` : "",
    slepName && slepName !== "Sin SLEP" ? slepName : "",
    communeCode ? `Comuna ${communeCode}` : "",
  ]
    .filter(Boolean)
    .join(" · ");
}

function higherStageMeta(knowledgeArea: string, modality: string, globalLevel: string) {
  return [knowledgeArea, modality, globalLevel].filter(Boolean).join(" · ");
}

function higherContextMeta(campusName: string, schedule: string, campusCommune: string) {
  return [campusName, schedule, campusCommune].filter(Boolean).join(" · ");
}

function transitionWindowCopy(windowLabel: string, gapToHigherYears: number) {
  if (windowLabel) {
    return `Paso detectado en la ventana ${windowLabel}.`;
  }

  if (gapToHigherYears > 0) {
    return `No hay paso directo; se observa un gap de ${gapToHigherYears} anio(s).`;
  }

  return "No hay una ventana de transicion escolar -> superior resuelta en Gold.";
}

