function readJsonFile<T>(filePath: string): T | null {
  if (!fs.existsSync(filePath)) {
    return null;
  }

  try {
    return JSON.parse(fs.readFileSync(filePath, "utf-8")) as T;
  } catch {
    return null;
  }
}

function parseCsvLine(line: string) {
  const cells: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    const next = line[index + 1];

    if (char === "\"") {
      if (inQuotes && next === "\"") {
        current += "\"";
        index += 1;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }

    if (char === "," && !inQuotes) {
      cells.push(current);
      current = "";
      continue;
    }

    current += char;
  }

  cells.push(current);
  return cells;
}

function readCsvRows(filePath: string) {
  if (!fs.existsSync(filePath)) {
    return [] as Record<string, string>[];
  }

  const content = fs.readFileSync(filePath, "utf-8").replace(/^\uFEFF/, "").trim();
  if (!content) {
    return [] as Record<string, string>[];
  }

  const lines = content.split(/\r?\n/);
  const headers = parseCsvLine(lines[0]);

  return lines.slice(1).filter(Boolean).map((line) => {
    const values = parseCsvLine(line);
    return headers.reduce<Record<string, string>>((row, header, index) => {
      row[header] = values[index] ?? "";
      return row;
    }, {});
  });
}

function readGzipCsvRows(filePath: string) {
  if (!fs.existsSync(filePath)) {
    return [] as Record<string, string>[];
  }

  const content = zlib.gunzipSync(fs.readFileSync(filePath)).toString("utf-8").replace(/^\uFEFF/, "").trim();
  if (!content) {
    return [] as Record<string, string>[];
  }

  const lines = content.split(/\r?\n/);
  const headers = parseCsvLine(lines[0]);

  return lines.slice(1).filter(Boolean).map((line) => {
    const values = parseCsvLine(line);
    return headers.reduce<Record<string, string>>((row, header, index) => {
      row[header] = values[index] ?? "";
      return row;
    }, {});
  });
}

function toNumber(value: string | number | undefined) {
  if (typeof value === "number") {
    return value;
  }

  const parsed = Number.parseFloat(String(value ?? "").trim());
  return Number.isFinite(parsed) ? parsed : 0;
}

function toBool(value: string | boolean | undefined) {
  if (typeof value === "boolean") {
    return value;
  }

  return ["true", "1", "yes"].includes(String(value ?? "").trim().toLowerCase());
}

function normalizeDigits(value: string | undefined) {
  return String(value ?? "").replace(/\D+/g, "");
}

function trajectoryPrefix(value: string) {
  const digits = normalizeDigits(value);
  return digits ? digits.padStart(3, "0").slice(0, 3) : "000";
}

