function readStudentTrajectoryLookupRow(rawMrun: string): StudentTrajectoryLookupRow | null {
  const canonicalIdValue = normalizeDigits(rawMrun);
  if (!canonicalIdValue) {
    return null;
  }

  const filePath = absPath(
    "warehouse",
    "gold",
    "public",
    "student_trajectory_lookup",
    "by_prefix",
    `${trajectoryPrefix(canonicalIdValue)}.csv.gz`
  );

  const row = readGzipCsvRows(filePath).find((item) => normalizeDigits(item.canonicalIdValue) === canonicalIdValue);
  if (!row) {
    return null;
  }

  return {
    canonicalStudentKey: row.canonicalStudentKey,
    canonicalIdValue: normalizeDigits(row.canonicalIdValue),
    firstAnyYear: toNumber(row.firstAnyYear),
    lastAnyYear: toNumber(row.lastAnyYear),
    schoolPresenceFlag: toBool(row.schoolPresenceFlag),
    firstSchoolYear: toNumber(row.firstSchoolYear),
    lastSchoolYear: toNumber(row.lastSchoolYear),
    schoolYearCount: toNumber(row.schoolYearCount),
    higherPresenceFlag: toBool(row.higherPresenceFlag),
    firstHigherYear: toNumber(row.firstHigherYear),
    lastHigherYear: toNumber(row.lastHigherYear),
    higherYearCount: toNumber(row.higherYearCount),
    domainsSeen: row.domainsSeen,
    trajectoryStage: row.trajectoryStage,
    gapToHigherYears: toNumber(row.gapToHigherYears),
    transitionWindowLabel: row.transitionWindowLabel,
    bridgeAliasCount: toNumber(row.bridgeAliasCount),
    bridgeConflictCount: toNumber(row.bridgeConflictCount),
  };
}

function pythonCandidates() {
  const candidates: Array<{ command: string; argsPrefix: string[] }> = [];
  const localAppData = process.env.LOCALAPPDATA;
  const userProfile = process.env.USERPROFILE;
  const absoluteCandidates = [
    process.env.PYTHON,
    absPath(".venv", "Scripts", "python.exe"),
    localAppData ? path.join(localAppData, "Programs", "Python", "Python312", "python.exe") : "",
    userProfile ? path.join(userProfile, "AppData", "Local", "Programs", "Python", "Python312", "python.exe") : "",
  ].filter(Boolean) as string[];

  for (const candidate of absoluteCandidates) {
    if (fs.existsSync(candidate)) {
      candidates.push({ command: candidate, argsPrefix: [] });
    }
  }

  candidates.push({ command: "python3", argsPrefix: [] });
  candidates.push({ command: "python", argsPrefix: [] });
  candidates.push({ command: "py", argsPrefix: ["-3"] });
  return candidates;
}

