function readStudentTrajectoryDetailFromSilver(lookup: StudentTrajectoryLookupRow) {
  const scriptPath = absPath("scripts", "find_student_trajectory.py");
  if (!fs.existsSync(scriptPath)) {
    return {
      schoolTimeline: [] as StudentTrajectorySchoolRow[],
      higherTimeline: [] as StudentTrajectoryHigherRow[],
    };
  }

  const args = [
    scriptPath,
    "--mrun",
    lookup.canonicalIdValue,
    "--first-school-year",
    String(lookup.firstSchoolYear || 0),
    "--last-school-year",
    String(lookup.lastSchoolYear || 0),
    "--first-higher-year",
    String(lookup.firstHigherYear || 0),
    "--last-higher-year",
    String(lookup.lastHigherYear || 0),
  ];

  const failures: string[] = [];

  for (const candidate of pythonCandidates()) {
    const result = spawnSync(candidate.command, [...candidate.argsPrefix, ...args], {
      cwd: ROOT,
      encoding: "utf-8",
      windowsHide: true,
      timeout: 120000,
    });

    if (result.error) {
      failures.push(`${candidate.command}: ${result.error.message}`);
      continue;
    }

    if (result.status !== 0) {
      const stderr = String(result.stderr ?? "").trim();
      failures.push(`${candidate.command}: ${stderr || `exit ${result.status ?? "unknown"}`}`);
      continue;
    }

    try {
      const payload = JSON.parse(String(result.stdout ?? "{}")) as {
        schoolTimeline?: Array<Record<string, string | number | undefined>>;
        higherTimeline?: Array<Record<string, string | number | undefined>>;
      };

      return {
        schoolTimeline: (payload.schoolTimeline ?? [])
          .map((row) => normalizeStudentTrajectorySchoolRow(row))
          .sort((left, right) => left.academicYear - right.academicYear),
        higherTimeline: (payload.higherTimeline ?? [])
          .map((row) => normalizeStudentTrajectoryHigherRow(row))
          .sort((left, right) => left.academicYear - right.academicYear),
      };
    } catch (error) {
      failures.push(`${candidate.command}: invalid JSON response`);
    }
  }

  console.error(
    `[trajectory] failed to resolve detail for MRUN ${lookup.canonicalIdValue}: ${failures.join(" | ")}`
  );
  return {
    schoolTimeline: [] as StudentTrajectorySchoolRow[],
    higherTimeline: [] as StudentTrajectoryHigherRow[],
  };
}

