function buildMedallionStatus(): MedallionInternalStatus {
  const fallback = emptyMedallionStatus();
  const bronzeManifest = readJsonFile<{
    generatedAt?: string;
    sources?: Array<{
      sourceId?: string;
      label?: string;
      status?: string;
      fileCount?: number;
      targetTable?: string;
      acceptedExtensions?: string[];
      requiredColumns?: string[];
      incomingPath?: string;
      archivePath?: string;
    }>;
  }>(absPath("warehouse", "bronze", "internal", "source_manifest.json"));
  const silverSummary = readJsonFile<{
    generatedAt?: string;
    source?: {
      bronzeEnrollmentStatus?: string;
    };
    artifacts?: Record<string, string>;
    files?: {
      discovered?: number;
      materialized?: number;
      rejected?: number;
      awaitingFiles?: boolean;
    };
    counts?: {
      studentRowsWritten?: number;
      enrollmentRowsWritten?: number;
    };
    statuses?: {
      enrollmentStatusCounts?: Record<string, number>;
    };
  }>(absPath("warehouse", "silver", "internal", "enrollment", "materialization_summary.json"));

  const bronzeSources: BronzeInternalSourceStatus[] = (bronzeManifest?.sources ?? []).map((source) => ({
    sourceId: source.sourceId ?? "",
    label: source.label ?? "",
    status: source.status ?? "awaiting_files",
    fileCount: toNumber(source.fileCount),
    targetTable: source.targetTable ?? "",
    acceptedExtensions: Array.isArray(source.acceptedExtensions) ? source.acceptedExtensions : [],
    requiredColumns: Array.isArray(source.requiredColumns) ? source.requiredColumns : [],
    incomingPath: source.incomingPath ?? "",
    archivePath: source.archivePath ?? "",
  }));

  const totalFiles = bronzeSources.reduce((sum, source) => sum + source.fileCount, 0);
  const readyForMapping = bronzeSources.filter((source) => source.status === "ready_for_mapping").length;

  return {
    bronzeInternal: {
      exists: Boolean(bronzeManifest),
      generatedAt: bronzeManifest?.generatedAt ?? fallback.bronzeInternal.generatedAt,
      sourceCount: bronzeSources.length,
      readyForMapping,
      awaitingFiles: bronzeSources.filter((source) => source.status === "awaiting_files").length,
      totalFiles,
      sources: bronzeSources,
    },
    silverInternalEnrollment: {
      exists: Boolean(silverSummary),
      generatedAt: silverSummary?.generatedAt ?? fallback.silverInternalEnrollment.generatedAt,
      discoveredFiles: toNumber(silverSummary?.files?.discovered),
      materializedFiles: toNumber(silverSummary?.files?.materialized),
      rejectedFiles: toNumber(silverSummary?.files?.rejected),
      awaitingFiles: silverSummary?.files?.awaitingFiles ?? true,
      bronzeEnrollmentStatus:
        silverSummary?.source?.bronzeEnrollmentStatus ?? fallback.silverInternalEnrollment.bronzeEnrollmentStatus,
      studentRowsWritten: toNumber(silverSummary?.counts?.studentRowsWritten),
      enrollmentRowsWritten: toNumber(silverSummary?.counts?.enrollmentRowsWritten),
      enrollmentStatusCounts:
        silverSummary?.statuses?.enrollmentStatusCounts ?? fallback.silverInternalEnrollment.enrollmentStatusCounts,
      artifacts: silverSummary?.artifacts ?? fallback.silverInternalEnrollment.artifacts,
    },
  };
}

