export function findStudentTrajectoryByMrun(rawMrun: string) {
  const canonicalIdValue = normalizeDigits(rawMrun);
  if (!canonicalIdValue) {
    return null;
  }

  if (trajectoryCache.has(canonicalIdValue)) {
    return trajectoryCache.get(canonicalIdValue) ?? null;
  }

  const lookup = readStudentTrajectoryLookupRow(canonicalIdValue);
  if (!lookup) {
    trajectoryCache.set(canonicalIdValue, null);
    return null;
  }

  const detail: StudentTrajectoryDetail = {
    lookup,
    ...readStudentTrajectoryDetailFromSilver(lookup),
  };
  trajectoryCache.set(canonicalIdValue, detail);
  return detail;
}

