  const priorityCommune = multiyear.priorityCommunes[0] ?? {
    name: "Sin dato",
    regionName: "Sin dato",
    latestDiscontinuityRate: 0,
    latestTrackedStudents: 0,
  };
  const prioritySchool = multiyear.prioritySchools[0] ?? {
    name: "Sin dato",
    latestDiscontinuityRate: 0,
    latestTrackedStudents: 0,
  };
  const adultPriorityCommune = multiyear.priorityCommunesSegmented.find((item) => item.segment === "adult");
  const regularPriorityCommune = multiyear.priorityCommunesSegmented.find((item) => item.segment === "regular");
  const topDependencyGroup = multiyear.priorityDependencyGroups[0];
  const topSlep = multiyear.prioritySleps[0];

  return {
    heroMetrics: [
      {
        label: "Continuidad escolar 2024-2025",
        value: formatPct(continuity.schoolContinuationRate),
        detail: `${continuity.continuedInSchool.toLocaleString("es-CL")} estudiantes siguen en escolar.`
      },
      {
        label: "Paso a educacion superior",
        value: formatPct(continuity.higherTransitionRate),
        detail: `${continuity.continuedInHigher.toLocaleString("es-CL")} estudiantes aparecen en superior 2025.`
      },
      {
        label: "Discontinuidad proxy",
        value: formatPct(continuity.discontinuityRate),
        detail: `${continuity.notFound2025.toLocaleString("es-CL")} trayectorias no tuvieron match 2025.`
      },
      {
        label: "Matricula escolar 2025",
        value: snapshot.school2025.totalEnrollment.toLocaleString("es-CL"),
        detail: `${snapshot.school2025.uniqueStudents.toLocaleString("es-CL")} estudiantes unicos observados.`
      },
      {
        label: "Cobertura historica publica",
        value: `${historical.school.minYear}-${historical.higher.maxYear}`,
        detail: `Escolar ${historical.school.minYear}-${historical.school.maxYear}; superior ${historical.higher.minYear}-${historical.higher.maxYear}.`
      },
      {
        label: "Serie comparable multianual",
        value: `${multiyear.summary.comparableWindowCount} ventanas`,
        detail: latestComparableWindow.windowLabel
          ? `Ultima ventana comparable ${latestComparableWindow.windowLabel}.`
          : "Aun no hay ventanas comparables materializadas."
      },
      {
        label: "Trayectorias indexadas",
        value: trajectoryLookup.totalStudents.toLocaleString("es-CL"),
        detail: `${trajectoryLookup.prefixPartitionCount.toLocaleString("es-CL")} particiones para busqueda por MRUN.`
      }
    ],
    insights: [
      `${riskRegion.name} lidera la discontinuidad proxy con ${formatPct(riskRegion.discontinuityRate)}.`,
      `${stableRegion.name} es la region mas estable del corte cargado con ${formatPct(100 - stableRegion.discontinuityRate)} de continuidad/progresion observada.`,
      `${riskSchool.name} aparece como foco escolar prioritario con ${formatPct(riskSchool.discontinuityRate)}.`,
      highestDiscontinuityWindow.windowLabel
        ? `La ventana comparable mas critica fue ${highestDiscontinuityWindow.windowLabel} con ${formatPct(highestDiscontinuityWindow.discontinuityRate)}.`
        : "La serie comparable multianual todavia no esta disponible.",
      `${priorityCommune.name} encabeza la prioridad multianual reciente con ${formatPct(priorityCommune.latestDiscontinuityRate)} en su ultima ventana observada.`,
      `${prioritySchool.name} aparece como establecimiento persistente a intervenir con base ${prioritySchool.latestTrackedStudents.toLocaleString("es-CL")}.`,
      adultPriorityCommune && regularPriorityCommune
        ? `La segmentacion separa ${regularPriorityCommune.name} como foco regular y ${adultPriorityCommune.name} como foco de adultos.`
        : "La priorizacion segmentada por adultos vs regular aun no esta materializada.",
      topDependencyGroup
        ? `${topDependencyGroup.name} aparece como corte de dependencia mas expuesto en segmento ${topDependencyGroup.segment}.`
        : "La priorizacion por dependencia aun no esta disponible.",
      topSlep
        ? `${topSlep.name} aparece como SLEP mas expuesto en la ultima ventana util para su segmento ${topSlep.segment}.`
        : "La priorizacion por SLEP aun no esta disponible.",
      `${topCommune.label} concentra ${topCommune.value.toLocaleString("es-CL")} matriculas escolares 2025 (${formatPct(topCommune.shareOfEnrollment)}).`,
      `${topArea.label} lidera superior y ${topModality.label} domina la modalidad observada en 2025.`,
      `${readiness.readyOnGold} modulos ya tienen lectura sobre Gold, ${readiness.partial} estan parciales y ${readiness.blocked} siguen bloqueados por falta de datos internos.`,
      medallion.bronzeInternal.exists
        ? `Bronze interno expone ${medallion.bronzeInternal.sourceCount} fuentes con ${medallion.bronzeInternal.totalFiles} archivo(s) actualmente en dropzones.`
        : "Bronze interno aun no esta materializado.",
      medallion.silverInternalEnrollment.exists
        ? `Silver interno enrollment descubrio ${medallion.silverInternalEnrollment.discoveredFiles} archivo(s) y materializo ${medallion.silverInternalEnrollment.enrollmentRowsWritten.toLocaleString("es-CL")} filas.`
        : "Silver interno enrollment aun no esta materializado.",
    ],
    medallion,
    prompts: [
      "Dame un resumen general",
      "Esta hecho con todas las bases historicas?",
      "Busca la trayectoria del MRUN 12345678",
      "Como va bronze y silver interno?",
      "Como cambia la discontinuidad en el tiempo?",
      "Que comunas debo priorizar en multianual?",
      "Que cambia entre adultos y regular?",
      "Que dependencia o SLEP debo priorizar?",
      "Que comunas concentran la matricula escolar?",
      "Que regiones muestran mas discontinuidad?",
      "Que areas y modalidades dominan en superior?",
      "Que modulos estan listos para operar con Gold?",
    ]
  };
}

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

