const state = {
  items: [],
  canons: [],
  dimensiones: [],
  lastGenerated: null,
  filters: {
    q: "",
    anio: "",
    dimension_id: "",
    subdimension: "",
    actor: "",
    grado: "",
  },
};

function byId(id) {
  return document.getElementById(id);
}

function fmt(v) {
  if (v === null || v === undefined || Number.isNaN(v)) return "-";
  return `${v}`;
}

function shortText(txt, max = 120) {
  const t = `${txt || ""}`.trim();
  return t.length > max ? `${t.slice(0, max)}...` : t;
}

async function api(path, opts = {}) {
  const res = await fetch(path, opts);
  if (!res.ok) {
    let detail = "";
    try {
      const body = await res.json();
      detail = body.detail ? `: ${body.detail}` : "";
    } catch (_) {
      // no-op
    }
    throw new Error(`HTTP ${res.status}${detail}`);
  }
  return res.json();
}

function setHealth(ok, text) {
  const pill = byId("health-pill");
  pill.className = `pill ${ok ? "pill-ok" : "pill-bad"}`;
  pill.textContent = text;
}

function buildQuery(obj) {
  const q = new URLSearchParams();
  Object.entries(obj).forEach(([k, v]) => {
    if (v !== undefined && v !== null && `${v}`.trim() !== "") {
      q.set(k, `${v}`.trim());
    }
  });
  return q.toString();
}

function fillYearFilter() {
  const sel = byId("filter-anio");
  const years = [];
  for (let y = 2015; y <= 2030; y += 1) years.push(y);
  sel.innerHTML = '<option value="">Todos</option>';
  years.forEach((y) => {
    const opt = document.createElement("option");
    opt.value = `${y}`;
    opt.textContent = `${y}`;
    sel.appendChild(opt);
  });
}

function renderDimensiones(dimensiones) {
  state.dimensiones = dimensiones || [];
  const f = byId("filter-dimension");
  const g = byId("gen-dimension");
  f.innerHTML = '<option value="">Todas</option>';
  g.innerHTML = '<option value="">Selecciona...</option>';
  state.dimensiones.forEach((d) => {
    const label = `${d.dimension_id} - ${d.nombre}`;
    const optF = document.createElement("option");
    optF.value = `${d.dimension_id}`;
    optF.textContent = label;
    f.appendChild(optF);

    const optG = document.createElement("option");
    optG.value = `${d.dimension_id}`;
    optG.textContent = label;
    g.appendChild(optG);
  });
}

function renderSubdimensionOptions(rows) {
  const dl = byId("subdim-options");
  if (!dl) return;
  dl.innerHTML = "";
  const seen = new Set();
  (rows || []).forEach((r) => {
    const name = `${r.nombre || ""}`.trim();
    if (!name || seen.has(name.toLowerCase())) return;
    seen.add(name.toLowerCase());
    const opt = document.createElement("option");
    opt.value = name;
    dl.appendChild(opt);
  });
}

function renderItems(items) {
  state.items = items || [];
  byId("items-count").textContent = `${state.items.length} items`;
  const tbody = byId("items-table").querySelector("tbody");
  tbody.innerHTML = "";

  state.items.forEach((row) => {
    const tr = document.createElement("tr");
    const canon = row.canon_id ? `<span class="canon-link" data-canon="${row.canon_id}">${row.canon_id}</span>` : "-";
    tr.innerHTML = `
      <td>${fmt(row.item_id)}</td>
      <td>${fmt(row.anio_creacion)}</td>
      <td>${canon}</td>
      <td>${fmt(row.dimension_nombre)}</td>
      <td>${fmt(row.subdimension_raw)}</td>
      <td>${fmt(row.actor)}</td>
      <td>${fmt(row.grado)}</td>
      <td>${fmt(row.np_raw)}</td>
      <td title="${(row.texto || "").replace(/"/g, "&quot;")}">${shortText(row.texto, 130)}</td>
    `;
    tr.addEventListener("click", () => {
      byId("suggest-item-id").value = `${row.item_id || ""}`;
      loadItemDetail(row.item_id);
    });
    tbody.appendChild(tr);
  });

  tbody.querySelectorAll(".canon-link").forEach((el) => {
    el.addEventListener("click", (ev) => {
      ev.stopPropagation();
      openCanonDetail(Number(el.dataset.canon));
      activateTab("longitudinal");
    });
  });
}

function renderItemDetail(data) {
  const box = byId("item-detail");
  if (!data || !data.item) {
    box.classList.add("muted");
    box.textContent = "No hay detalle del item.";
    return;
  }
  box.classList.remove("muted");
  const item = data.item || {};
  const mapas = data.mapas_matriz || [];
  const resultados = data.resultados_aplicacion || [];
  const irt = data.parametros_irt || [];
  const clasico = data.resumen_clasico || [];

  const mapa = mapas[0] || {};
  const rowsRes = resultados
    .slice(0, 8)
    .map((r) => `<li>${fmt(r.anio)} | match=${fmt(r.match_tipo)} | media=${fmt(r.media)} | n=${fmt(r.total_respuestas)}</li>`)
    .join("");
  const rowsIrt = irt
    .slice(-5)
    .map((r) => `<li>${fmt(r.anio)} | a=${fmt(r.param_a)} | b=${fmt(r.param_b)} | c=${fmt(r.param_c)} | modelo=${fmt(r.modelo)}</li>`)
    .join("");

  box.innerHTML = `
    <h3>Ficha Item ${fmt(item.item_id)}</h3>
    <p><b>Codigo:</b> ${fmt(item.codigo)} | <b>Canon:</b> ${fmt(item.canon_id)} | <b>Ano:</b> ${fmt(item.anio_creacion)}</p>
    <p><b>Dimension:</b> ${fmt(item.dimension_nombre)} | <b>Subdimension:</b> ${fmt(mapa.subdimension_canon || mapa.subdimension_raw)}</p>
    <p><b>Actor:</b> ${fmt(mapa.actor)} | <b>Grado:</b> ${fmt(mapa.grado)} | <b>Forma:</b> ${fmt(mapa.forma)} | <b>NP:</b> ${fmt(mapa.np_raw)}</p>
    <p>${shortText(item.texto, 320)}</p>
    <p><b>Resultados por item:</b> ${resultados.length} | <b>Clasico:</b> ${clasico.length} | <b>IRT:</b> ${irt.length}</p>
    <div><b>Ultimos resultados</b><ul>${rowsRes || "<li>Sin datos</li>"}</ul></div>
    <div><b>IRT por ano</b><ul>${rowsIrt || "<li>Sin IRT cargado</li>"}</ul></div>
  `;
}

function renderLongitudinal(canons) {
  state.canons = canons || [];
  const tbody = byId("canon-table").querySelector("tbody");
  tbody.innerHTML = "";
  state.canons.forEach((c) => {
    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td><span class="canon-link" data-canon="${c.canon_id}">${c.canon_id}</span></td>
      <td>${fmt(c.n_items)}</td>
      <td>${fmt(c.n_anios)}</td>
      <td>${fmt(c.anio_inicio)} - ${fmt(c.anio_fin)}</td>
    `;
    tbody.appendChild(tr);
  });

  tbody.querySelectorAll(".canon-link").forEach((el) => {
    el.addEventListener("click", () => openCanonDetail(Number(el.dataset.canon)));
  });
}

function renderCanonDetail(canonId, rows) {
  const box = byId("canon-detail");
  if (!rows || rows.length === 0) {
    box.classList.add("muted");
    box.textContent = `No hay detalle para canon ${canonId}.`;
    return;
  }
  box.classList.remove("muted");
  const html = rows
    .map((r) => {
      return `
        <article class="timeline-item">
          <h4>${fmt(r.anio_creacion)} | Item ${fmt(r.item_id)} | ${fmt(r.relacion)}</h4>
          <p>Dimension: ${fmt(r.dimension_nombre)} | Subdimension: ${fmt(r.subdimension_raw)} | Actor: ${fmt(r.actor)} | Grado: ${fmt(r.grado)} | NP: ${fmt(r.np_raw)}</p>
          <p>Score: ${fmt(r.score_similitud)}</p>
          <p>${shortText(r.texto, 220)}</p>
        </article>
      `;
    })
    .join("");
  box.innerHTML = `<h3>Serie canon ${canonId}</h3>${html}`;
}

function renderSummary(stats) {
  const summary = byId("summary-list");
  summary.innerHTML = "";
  const banco = stats.banco || {};
  const hom = stats.homologacion || {};
  [
    `Items activos: ${fmt(banco.total_items)}`,
    `Dimensiones: ${fmt(banco.total_dimensiones)}`,
    `Mapeos matriz: ${fmt(hom.items_matriz_map)}`,
    `Equivalencias longitudinales (filas): ${fmt(hom.item_equivalencias)}`,
    `Series canon totales: ${fmt(hom.series_canon)}`,
    `Series canon 2+ anos: ${fmt(hom.series_canon_multianio)}`,
    `Resultados por aplicacion cargados: ${fmt(hom.resultados_aplicacion)}`,
  ].forEach((txt) => {
    const li = document.createElement("li");
    li.textContent = txt;
    summary.appendChild(li);
  });
}

function activateTab(name) {
  document.querySelectorAll(".tab-btn").forEach((b) => {
    b.classList.toggle("active", b.dataset.tab === name);
  });
  document.querySelectorAll(".tab-pane").forEach((p) => {
    p.classList.toggle("active", p.id === `tab-${name}`);
  });
}

function appendChatMessage(type, text) {
  const box = byId("chat-log");
  const d = document.createElement("div");
  d.className = `msg ${type === "user" ? "msg-user" : "msg-agent"}`;
  d.textContent = text;
  box.appendChild(d);
  box.scrollTop = box.scrollHeight;
}

async function loadStats() {
  const stats = await api("/api/stats");
  const banco = stats.banco || {};
  const hom = stats.homologacion || {};

  byId("stat-items").textContent = fmt(banco.total_items);
  byId("stat-map").textContent = fmt(hom.items_matriz_map);
  byId("stat-canon").textContent = fmt(hom.series_canon);
  byId("stat-multiyear").textContent = fmt(hom.series_canon_multianio);
  byId("stat-resultados").textContent = fmt(hom.resultados_aplicacion);

  renderSummary(stats);
  return stats;
}

async function loadDimensiones() {
  const data = await api("/api/dimensiones");
  renderDimensiones(data);
}

async function loadSubdimensiones(dimensionId = "") {
  const qs = buildQuery({ dimension_id: dimensionId || "" });
  const data = await api(`/api/subdimensiones${qs ? `?${qs}` : ""}`);
  renderSubdimensionOptions(data);
}

async function loadLlmStatus() {
  const out = await api("/api/llm-status");
  const box = byId("llm-status");
  if (!box) return;
  if (out.enabled) {
    box.textContent = `LLM: ${fmt(out.provider)} | ${fmt(out.model)} (activo)`;
    box.classList.remove("muted");
  } else {
    box.textContent = "LLM: modo local (sin API key)";
    box.classList.add("muted");
  }
}

async function loadItems() {
  const params = buildQuery({
    q: state.filters.q,
    anio: state.filters.anio,
    dimension_id: state.filters.dimension_id,
    subdimension: state.filters.subdimension,
    actor: state.filters.actor,
    grado: state.filters.grado,
    limit: 1000,
  });
  const data = await api(`/api/items?${params}`);
  renderItems(data);
  if (Array.isArray(data) && data.length > 0) {
    await loadItemDetail(data[0].item_id);
  } else {
    byId("item-detail").textContent = "Sin items con este filtro.";
  }
}

async function loadLongitudinal() {
  const data = await api("/api/longitudinal?min_anios=2&limit=2000");
  renderLongitudinal(data);
}

async function openCanonDetail(canonId) {
  const rows = await api(`/api/longitudinal/${canonId}`);
  renderCanonDetail(canonId, rows);
}

async function loadItemDetail(itemId) {
  if (!itemId) return;
  try {
    const data = await api(`/api/item/${itemId}`);
    renderItemDetail(data);
  } catch (err) {
    byId("item-detail").textContent = `No pude cargar detalle del item: ${err.message}`;
  }
}

async function sendChat() {
  const t = byId("chat-text");
  const question = `${t.value || ""}`.trim();
  if (!question) return;
  appendChatMessage("user", question);
  t.value = "";
  try {
    const out = await api("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
    });
    appendChatMessage("agent", out.answer || "(sin respuesta)");
  } catch (err) {
    appendChatMessage("agent", `Error consultando agente: ${err.message}`);
  }
}

async function generateItem() {
  const dimension_id = Number(byId("gen-dimension").value || "");
  const dificultad = byId("gen-dificultad").value || "moderada";
  const subdimension = `${byId("gen-subdimension").value || ""}`.trim();
  const instrucciones = `${byId("gen-instrucciones").value || ""}`.trim();
  if (!dimension_id) {
    byId("gen-result").textContent = "Selecciona una dimension.";
    return;
  }
  byId("gen-result").textContent = "Generando...";
  try {
    const out = await api("/api/generate-item", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dimension_id, dificultad, subdimension, instrucciones }),
    });
    const lines = [];
    lines.push(`Texto: ${out.texto || "-"}`);
    lines.push(`Direccion: ${out.direccion || "-"}`);
    lines.push(`Dificultad: ${out.nivel_dificultad_estimado || "-"}`);
    lines.push(`Metodo: ${out.metodo_generacion || "-"}`);
    if (Array.isArray(out.opciones_respuesta) && out.opciones_respuesta.length) {
      lines.push("Opciones:");
      out.opciones_respuesta.forEach((op) => lines.push(`- ${op}`));
    }
    if (out.justificacion) lines.push(`Justificacion: ${out.justificacion}`);
    byId("gen-result").textContent = lines.join("\n");
    state.lastGenerated = {
      dimension_id,
      subdimension,
      dificultad_objetivo: dificultad,
      texto: out.texto || "",
      opciones_respuesta: out.opciones_respuesta || [],
      direccion: out.direccion || "positiva",
      justificacion: out.justificacion || null,
      metadata: {
        origen_ui: "dashboard_web",
        nivel_dificultad_estimado: out.nivel_dificultad_estimado || null,
        metodo_generacion: out.metodo_generacion || "heuristico_local",
      },
    };
    byId("approve-result").textContent = "Item generado. Puedes aprobar y guardar en repositorio.";
  } catch (err) {
    byId("gen-result").textContent = `Error: ${err.message}`;
  }
}

async function approveGeneratedItem() {
  if (!state.lastGenerated || !state.lastGenerated.texto) {
    byId("approve-result").textContent = "Primero genera un item.";
    return;
  }
  byId("approve-result").textContent = "Guardando item aprobado...";
  try {
    const out = await api("/api/approve-item", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(state.lastGenerated),
    });
    byId("approve-result").textContent = `Guardado: ${out.codigo_repo} | item_id=${out.item_id} | canon=${out.canon_id}`;
    await loadItems();
    await loadStats();
    await loadRepoItems();
  } catch (err) {
    byId("approve-result").textContent = `Error al aprobar: ${err.message}`;
  }
}

function renderRepoItems(items) {
  const box = byId("repo-items");
  if (!items || items.length === 0) {
    box.textContent = "Sin items aprobados.";
    return;
  }
  const lines = items.slice(0, 12).map((r) => {
    return `${r.codigo_repo} | item ${r.item_id} | dim ${r.dimension_nombre || r.dimension_id} | ${shortText(r.texto, 72)}`;
  });
  box.textContent = lines.join("\n");
}

async function loadRepoItems() {
  try {
    const rows = await api("/api/repository/new-items?limit=50");
    renderRepoItems(rows);
  } catch (err) {
    byId("repo-items").textContent = `Error repo: ${err.message}`;
  }
}

async function suggestItem() {
  const itemId = Number(byId("suggest-item-id").value || "");
  if (!itemId) {
    byId("suggest-result").textContent = "Ingresa un item_id.";
    return;
  }
  byId("suggest-result").textContent = "Analizando...";
  try {
    const out = await api(`/api/suggest-item/${itemId}`);
    byId("suggest-result").textContent = JSON.stringify(out, null, 2);
  } catch (err) {
    byId("suggest-result").textContent = `Error: ${err.message}`;
  }
}

async function refreshAll() {
  try {
    setHealth(true, "Cargando...");
    await loadDimensiones();
    await loadSubdimensiones();
    await loadLlmStatus();
    await loadItems();
    await loadLongitudinal();
    await loadRepoItems();
    const stats = await loadStats();
    byId("stat-canon").textContent = fmt(stats.homologacion?.series_canon || 0);
    setHealth(true, "API activa");
  } catch (err) {
    setHealth(false, `Error API: ${err.message}`);
  }
}

function bindEvents() {
  byId("btn-refresh").addEventListener("click", refreshAll);
  byId("btn-apply").addEventListener("click", async () => {
    state.filters.q = byId("filter-q").value;
    state.filters.anio = byId("filter-anio").value;
    state.filters.dimension_id = byId("filter-dimension").value;
    state.filters.subdimension = byId("filter-subdimension").value;
    state.filters.actor = byId("filter-actor").value;
    state.filters.grado = byId("filter-grado").value;
    await loadItems();
    await loadStats();
  });
  byId("btn-clear").addEventListener("click", async () => {
    byId("filter-q").value = "";
    byId("filter-anio").value = "";
    byId("filter-dimension").value = "";
    byId("filter-subdimension").value = "";
    byId("filter-actor").value = "";
    byId("filter-grado").value = "";
    state.filters = { q: "", anio: "", dimension_id: "", subdimension: "", actor: "", grado: "" };
    await loadItems();
    await loadStats();
  });
  byId("btn-chat").addEventListener("click", sendChat);
  byId("btn-generate").addEventListener("click", generateItem);
  byId("btn-approve").addEventListener("click", approveGeneratedItem);
  byId("btn-suggest").addEventListener("click", suggestItem);
  byId("chat-text").addEventListener("keydown", (ev) => {
    if (ev.key === "Enter" && !ev.shiftKey) {
      ev.preventDefault();
      sendChat();
    }
  });

  byId("filter-dimension").addEventListener("change", async () => {
    await loadSubdimensiones(byId("filter-dimension").value);
  });
  byId("gen-dimension").addEventListener("change", async () => {
    await loadSubdimensiones(byId("gen-dimension").value);
  });

  document.querySelectorAll(".tab-btn").forEach((btn) => {
    btn.addEventListener("click", () => activateTab(btn.dataset.tab));
  });
}

async function checkHealth() {
  try {
    const info = await api("/api/health");
    setHealth(Boolean(info.ok), info.ok ? "API activa" : "API inactiva");
  } catch (err) {
    setHealth(false, `Sin conexion: ${err.message}`);
  }
}

async function boot() {
  fillYearFilter();
  bindEvents();
  await checkHealth();
  await refreshAll();
}

boot();

