const xlsx = require('xlsx');
const wb = xlsx.readFile('Matriz_Master.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const data = xlsx.utils.sheet_to_json(ws);

console.log('=== COLUMNAS ===');
console.log(Object.keys(data[0]).join(' | '));

console.log('\n=== PRIMERAS 25 FILAS (con Subdimension y Subdimension_nombre) ===');
data.slice(0, 25).forEach((row, i) => {
  console.log(`${i+1}. Ind:${row.Indicador} | Dim:${row.Dimension} | Sub:${row.Subdimension} | Nombre:"${row.Subdimension_nombre}"`);
});

console.log('\n=== MAPEO CODIGO -> SDIM (como lo hace R) ===');
const mapeo = data
  .filter(row => row.Subdimension && row.Dimension && row.Indicador)
  .map(row => ({
    codigo_col: row.Subdimension.toUpperCase(),
    sdim: `${row.Indicador}_${row.Dimension}_${row.Subdimension}`,
    label_sdim: row.Subdimension_nombre ? row.Subdimension_nombre.trim() : ''
  }));

mapeo.slice(0, 25).forEach((m, i) => {
  console.log(`${i+1}. ${m.codigo_col} -> ${m.sdim} -> "${m.label_sdim}"`);
});

const xlsx = require('xlsx');
const wb = xlsx.readFile('Matriz_Master.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const data = xlsx.utils.sheet_to_json(ws);

// Crear mapeo único como lo hace R
const mapeoUnico = new Map();
data
  .filter(row => row.Subdimension && row.Dimension && row.Indicador)
  .forEach(row => {
    const codigo_col = row.Subdimension.toUpperCase();
    const sdim = `${row.Indicador}_${row.Dimension}_${row.Subdimension}`;
    const label_sdim = row.Subdimension_nombre ? row.Subdimension_nombre.trim() : '';
    
    if (!mapeoUnico.has(codigo_col)) {
      mapeoUnico.set(codigo_col, { sdim, label_sdim });
    }
  });

console.log('=== MAPEO ÚNICO (codigo_col -> sdim -> label_sdim) ===');
console.log('Total códigos únicos:', mapeoUnico.size);
console.log('');

mapeoUnico.forEach((val, key) => {
  console.log(`${key} -> ${val.sdim} -> "${val.label_sdim}"`);
});

const fs = require('fs');

const env = fs.readFileSync('.env.local', 'utf8');
const urlMatch = env.match(/NEXT_PUBLIC_SUPABASE_URL=(.*)/);
const keyMatch = env.match(/NEXT_PUBLIC_SUPABASE_ANON_KEY=(.*)/);

const url = urlMatch[1].trim();
const key = keyMatch[1].trim();

async function check() {
    try {
        const res = await fetch(`${url}/rest/v1/polls?select=*&limit=1`, {
            headers: {
                'apikey': key,
                'Authorization': `Bearer ${key}`
            }
        });

        if (res.ok) {
            const data = await res.json();
            console.log('=> SUCCESS: Polls table exists. Data:', data);
        } else {
            const err = await res.json();
            console.log('=> ERROR: Polls table might not exist.', err);
        }
    } catch (error) {
        console.error('Fetch error:', error);
    }
}

check();

