"use client";

import { Button } from "@/components/ui/Button";
import { ExpensesService } from "@/lib/api";
import { DollarSign, Download, CheckCircle, Clock, AlertCircle, TrendingUp, CreditCard, Receipt, ArrowUpRight, Loader2 } from "lucide-react";
import { useAuth } from "@/lib/authContext";
import { useToast } from "@/components/ui/Toast";
import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Skeleton, SkeletonTable } from "@/components/ui/Skeleton";
import { ErrorBoundary } from "@/components/ui/ErrorBoundary";
export default function ExpensesPage() {
    const { user } = useAuth();
    const { toast } = useToast();
    const [expenses, setExpenses] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isPaying, setIsPaying] = useState<string | null>(null);

    useEffect(() => {
        const fetchExpenses = async () => {
            // For demo purposes, fallback to a mocked unitId if user isn't fully linked
            const activeUnit = user?.unitId || 'c4a96bdf-6f7f-4b02-8f9f-5c2f354f9aeb';
            try {
                setIsLoading(true);
                const data = await ExpensesService.getExpenses(activeUnit);

                // Map snake_case to camelCase
                const mapped = data.map((exp: any) => ({
                    id: exp.id,
                    unitId: exp.unit_id,
                    month: exp.month,
                    amount: Number(exp.amount),
                    status: exp.status,
                    dueDate: exp.due_date,
                    paidAt: exp.paid_at,
                    breakdown: exp.items || []
                }));

                setExpenses(mapped);
            } catch (error: any) {
                console.error("Error fetching expenses:", error?.message || error);
                // Mostrar estado vacío en vez de error toast
                setExpenses([]);
            } finally {
                setIsLoading(false);
            }
        };

        fetchExpenses();
    }, [user?.unitId, toast]);

    const handlePay = async (id: string) => {
        try {
            setIsPaying(id);
            await ExpensesService.payExpense(id);

            // Optimistic update
            setExpenses(prev => prev.map((exp: any) =>
                exp.id === id ? { ...exp, status: 'paid' as const } : exp
            ));

            toast({
                title: "Pago Exitoso",
                description: "La transacción ha sido procesada en la nube.",
                variant: "success",
            });
        } catch (error) {
            toast({
                title: "Error",
                description: "No se pudo procesar el pago.",
                variant: "destructive",
            });
        } finally {
            setIsPaying(null);
        }
    };

    const totalPending = expenses.filter((e: any) => e.status !== 'paid').reduce((acc: number, curr: any) => acc + curr.amount, 0);
    const totalPaid = expenses.filter((e: any) => e.status === 'paid').reduce((acc: number, curr: any) => acc + curr.amount, 0);
    const hasOverdue = expenses.some((e: any) => e.status === 'overdue');

    const getStatusConfig = (status: string) => {
        switch (status) {
            case 'paid': return {
                icon: CheckCircle,
                label: 'Pagado',
                bg: 'bg-emerald-50 dark:bg-emerald-500/10',
                text: 'text-emerald-700 dark:text-emerald-400',
                border: 'border-emerald-200 dark:border-emerald-500/20',
                ring: 'ring-emerald-500/20'
            };
            case 'pending': return {
                icon: Clock,
                label: 'Pendiente',
                bg: 'bg-amber-50 dark:bg-amber-500/10',
                text: 'text-amber-700 dark:text-amber-400',
                border: 'border-amber-200 dark:border-amber-500/20',
                ring: 'ring-amber-500/20'
            };
            case 'overdue': return {
                icon: AlertCircle,
                label: 'Vencido',
                bg: 'bg-red-50 dark:bg-red-500/10',
                text: 'text-red-700 dark:text-red-400',
                border: 'border-red-200 dark:border-red-500/20',
                ring: 'ring-red-500/20'
            };
            default: return {
                icon: Clock,
                label: status,
                bg: 'bg-slate-50 dark:bg-slate-700',
                text: 'text-slate-700 dark:text-slate-300',
                border: 'border-slate-200 dark:border-slate-600',
                ring: 'ring-slate-500/20'
            };
        }
    };

    const formatMonth = (monthStr: string) => {
        const [year, month] = monthStr.split('-');
        const date = new Date(parseInt(year), parseInt(month) - 1);
        return date.toLocaleDateString('es-CL', { month: 'long', year: 'numeric' });
    };

    return (
        <div className="max-w-6xl space-y-8">
            {/* Header */}
            <div>
                <div className="flex items-center gap-3 mb-2">
                    <div className="p-2 bg-gradient-to-br from-rose-500 to-pink-600 rounded-xl">
                        <DollarSign className="h-5 w-5 text-white" />
                    </div>
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Gastos Comunes</h1>
                </div>
                <p className="text-slate-500 dark:text-slate-400">
                    Historial de cobros y pagos de tu unidad • Depto {user?.unitId || '101'}
                </p>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Total Pending Card */}
                <div className={`relative overflow-hidden rounded-2xl p-6 ${hasOverdue ? 'bg-gradient-to-br from-red-500 to-pink-600' : 'bg-gradient-to-br from-rose-500 to-pink-600'} text-white shadow-xl shadow-rose-500/25`}>
                    <div className="absolute top-0 right-0 p-4 opacity-20">
                        <DollarSign className="h-24 w-24" />
                    </div>
                    <div className="relative">
                        <p className="text-white/80 text-sm font-medium">Total Pendiente</p>
                        <p className="text-4xl font-bold mt-2">${totalPending.toLocaleString('es-CL')}</p>
                        {hasOverdue && (
                            <div className="mt-3 flex items-center gap-2 text-sm">
                                <AlertCircle className="h-4 w-4" />
                                <span>Tienes pagos vencidos</span>
                            </div>
                        )}
                    </div>
                </div>

                {/* Total Paid Card */}
                <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-lg shadow-slate-200/50 dark:shadow-slate-950/50 border border-slate-100 dark:border-slate-700">
                    <div className="flex items-center justify-between mb-4">
                        <div className="p-3 bg-emerald-100 dark:bg-emerald-500/20 rounded-xl">
                            <TrendingUp className="h-5 w-5 text-emerald-600 dark:text-emerald-400" />
                        </div>
                        <span className="text-xs font-medium text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-500/10 px-2 py-1 rounded-full">
                            Al día
                        </span>
                    </div>
                    <p className="text-sm text-slate-500 dark:text-slate-400">Total Pagado</p>
                    <p className="text-2xl font-bold text-slate-900 dark:text-white mt-1">${totalPaid.toLocaleString('es-CL')}</p>
                </div>

                {/* Quick Pay Card */}
                <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-lg shadow-slate-200/50 dark:shadow-slate-950/50 border border-slate-100 dark:border-slate-700">
                    <div className="flex items-center justify-between mb-4">
                        <div className="p-3 bg-indigo-100 dark:bg-indigo-500/20 rounded-xl">
                            <CreditCard className="h-5 w-5 text-indigo-600 dark:text-indigo-400" />
                        </div>
                    </div>
                    <p className="text-sm text-slate-500 dark:text-slate-400">Métodos de Pago</p>
                    <div className="flex items-center gap-2 mt-3">
                        <div className="h-8 w-12 bg-gradient-to-r from-blue-600 to-blue-400 rounded-md flex items-center justify-center text-white text-xs font-bold">VISA</div>
                        <div className="h-8 w-12 bg-gradient-to-r from-red-500 to-orange-400 rounded-md flex items-center justify-center text-white text-xs font-bold">MC</div>
                        <div className="h-8 w-12 bg-gradient-to-r from-slate-700 to-slate-500 rounded-md flex items-center justify-center text-white text-xs font-bold">PAC</div>
                    </div>
                </div>
            </div>

            {/* Payment History Table */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg shadow-slate-200/50 dark:shadow-slate-950/50 border border-slate-100 dark:border-slate-700 overflow-hidden">
                <div className="p-6 border-b border-slate-100 dark:border-slate-700">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-slate-100 dark:bg-slate-700 rounded-xl">
                                <Receipt className="h-5 w-5 text-slate-600 dark:text-slate-400" />
                            </div>
                            <h2 className="text-lg font-bold text-slate-900 dark:text-white">Historial de Pagos</h2>
                        </div>
                        <button className="text-sm font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-300 flex items-center gap-1">
                            Descargar todo <Download className="h-4 w-4" />
                        </button>
                    </div>
                </div>

                <ErrorBoundary name="Historial de pagos">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 font-medium">
                                    <th className="px-6 py-4 text-left">Período</th>
                                    <th className="px-6 py-4 text-left">Vencimiento</th>
                                    <th className="px-6 py-4 text-left">Monto</th>
                                    <th className="px-6 py-4 text-left">Estado</th>
                                    <th className="px-6 py-4 text-right">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-700 relative">
                                {isLoading ? (
                                    <tr>
                                        <td colSpan={5} className="p-0">
                                            <SkeletonTable rows={3} />
                                        </td>
                                    </tr>
                                ) : (
                                    expenses.map((expense, idx) => {
                                        const status = getStatusConfig(expense.status);
                                        const StatusIcon = status.icon;

                                        return (
                                            <tr
                                                key={expense.id}
                                                className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors animate-slide-up opacity-0"
                                                style={{ animationDelay: `${idx * 0.05}s`, animationFillMode: 'forwards' }}
                                            >
                                                <td className="px-6 py-4">
                                                    <p className="font-semibold text-slate-900 dark:text-white capitalize">{formatMonth(expense.month)}</p>
                                                </td>
                                                <td className="px-6 py-4 text-slate-600 dark:text-slate-400">
                                                    {new Date(expense.dueDate).toLocaleDateString('es-CL', { day: 'numeric', month: 'short', year: 'numeric' })}
                                                </td>
                                                <td className="px-6 py-4">
                                                    <span className="text-lg font-bold text-slate-900 dark:text-white">
                                                        ${expense.amount.toLocaleString('es-CL')}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4">
                                                    <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold ${status.bg} ${status.text} ring-1 ring-inset ${status.ring}`}>
                                                        <StatusIcon className="h-3.5 w-3.5" />
                                                        {status.label}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4 text-right">
                                                    {expense.status !== 'paid' ? (
                                                        <button
                                                            onClick={() => handlePay(expense.id)}
                                                            disabled={isPaying === expense.id}
                                                            className="inline-flex items-center justify-center min-w-[140px] gap-2 px-4 py-2 bg-gradient-to-r from-rose-500 to-pink-500 text-white font-semibold rounded-xl shadow-lg shadow-rose-500/25 hover:shadow-xl hover:-translate-y-0.5 transition-all text-sm disabled:opacity-50 disabled:pointer-events-none"
                                                        >
                                                            {isPaying === expense.id ? (
                                                                <Loader2 className="h-4 w-4 animate-spin" />
                                                            ) : (
                                                                <>Pagar Ahora <ArrowUpRight className="h-4 w-4" /></>
                                                            )}
                                                        </button>
                                                    ) : (
                                                        <button className="inline-flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 font-medium rounded-xl hover:bg-slate-200 dark:hover:bg-slate-600 transition-colors text-sm">
                                                            <Download className="h-4 w-4" />
                                                            Comprobante
                                                        </button>
                                                    )}
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                </ErrorBoundary>

                {!isLoading && expenses.length === 0 && (
                    <div className="text-center py-12">
                        <DollarSign className="mx-auto h-12 w-12 text-slate-300 dark:text-slate-600 mb-4" />
                        <p className="text-slate-500 dark:text-slate-400">No hay registros de gastos comunes para esta unidad.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from 'react';
import { Bell, Info, AlertTriangle, Calendar, Plus, Megaphone, ArrowRight, Loader2 } from "lucide-react";
import { useAuth } from "@/lib/authContext";
import { AnnouncementsService } from "@/lib/api";
import { SkeletonAnnouncement } from "@/components/ui/Skeleton";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/Dialog";
import { useToast } from "@/components/ui/Toast";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";

export default function FeedPage() {
    const { user } = useAuth();
    const [announcements, setAnnouncements] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [newPost, setNewPost] = useState({ title: '', content: '', priority: 'info' });
    const { toast } = useToast();

    useEffect(() => {
        const fetchAnnouncements = async () => {
            try {
                setIsLoading(true);
                const data = await AnnouncementsService.getAnnouncements();
                // Map the snake_case data to camelCase for the UI
                const mappedData = data.map((ann: any) => ({
                    id: ann.id,
                    title: ann.title,
                    content: ann.content,
                    author: ann.author_name || 'Administración',
                    priority: ann.priority,
                    createdAt: ann.created_at,
                }));
                setAnnouncements(mappedData);
            } catch (error) {
                console.error("Error al cargar anuncios:", error);
                toast({
                    title: "Error de Conexión",
                    description: "No se pudieron cargar los comunicados.",
                    variant: "destructive",
                });
            } finally {
                setIsLoading(false);
            }
        };

        fetchAnnouncements();
    }, [toast]);

    const getIcon = (priority: string) => {
        switch (priority) {
            case 'alert': return AlertTriangle;
            case 'event': return Calendar;
            default: return Info;
        }
    };

    const getPriorityStyles = (priority: string) => {
        switch (priority) {
            case 'alert': return {
                badge: 'bg-red-100 dark:bg-red-500/20 text-red-700 dark:text-red-400 ring-red-600/20',
                icon: 'bg-red-100 dark:bg-red-500/20 text-red-600 dark:text-red-400',
                border: 'border-l-red-500',
                glow: 'shadow-red-500/5'
            };
            case 'event': return {
                badge: 'bg-purple-100 dark:bg-purple-500/20 text-purple-700 dark:text-purple-400 ring-purple-600/20',
                icon: 'bg-purple-100 dark:bg-purple-500/20 text-purple-600 dark:text-purple-400',
                border: 'border-l-purple-500',
                glow: 'shadow-purple-500/5'
            };
            default: return {
                badge: 'bg-blue-100 dark:bg-blue-500/20 text-blue-700 dark:text-blue-400 ring-blue-600/20',
                icon: 'bg-blue-100 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400',
                border: 'border-l-blue-500',
                glow: 'shadow-blue-500/5'
            };
        }
    };

    const getPriorityLabel = (priority: string) => {
        switch (priority) {
            case 'alert': return 'Urgente';
            case 'event': return 'Evento';
            default: return 'Información';
        }
    };

    const handlePostSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!user || user.role === 'resident') {
            toast({
                title: "Acceso Denegado",
                description: "No tienes permisos para publicar avisos.",
                variant: "destructive",
            });
            return;
        }

        try {
            const data = await AnnouncementsService.createAnnouncement({
                title: newPost.title,
                content: newPost.content,
                priority: newPost.priority as 'info' | 'alert' | 'event',
                author_id: user.id || '11111111-1111-1111-1111-111111111111',
                author_name: user.name || 'Administración'
            });

            const newAnn = {
                id: data.id,
                title: data.title,
                content: data.content,
                author: data.author_name || 'Administración',
                priority: data.priority,
                createdAt: data.created_at,
            };

            setAnnouncements([newAnn, ...announcements]);
            setIsDialogOpen(false);
            setNewPost({ title: '', content: '', priority: 'info' });
            toast({
                title: "Aviso Publicado",
                description: "La notificación ha sido enviada a todos los residentes.",
                variant: "success",
            });
        } catch (error) {
            console.error("Error creating post:", error);
            toast({
                title: "Error",
                description: "Hubo un problema al publicar el aviso.",
                variant: "destructive",
            });
        }
    };

    const getRelativeTime = (dateString: string) => {
        const date = new Date(dateString);
        const now = new Date();
        const diffInHours = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60));

        if (diffInHours < 1) return 'Hace un momento';
        if (diffInHours < 24) return `Hace ${diffInHours}h`;
        if (diffInHours < 48) return 'Ayer';
        return date.toLocaleDateString('es-CL', { day: 'numeric', month: 'short' });
    };

    return (
        <div className="max-w-4xl space-y-8">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl">
                            <Megaphone className="h-5 w-5 text-white" />
                        </div>
                        <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Muro de Avisos</h1>
                    </div>
                    <p className="text-slate-500 dark:text-slate-400">
                        Noticias y comunicados oficiales de la comunidad
                    </p>
                </div>
                {user?.role === 'admin' && (
                    <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
                        <DialogTrigger asChild>
                            <button className="inline-flex items-center gap-2 px-5 py-3 bg-gradient-to-r from-indigo-500 to-purple-600 text-white font-semibold rounded-xl shadow-lg shadow-indigo-500/25 hover:shadow-xl hover:shadow-indigo-500/30 hover:-translate-y-0.5 transition-all duration-300">
                                <Plus className="h-5 w-5" />
                                Publicar Aviso
                            </button>
                        </DialogTrigger>
                        <DialogContent>
                            <DialogHeader>
                                <DialogTitle>Nuevo Comunicado</DialogTitle>
                                <DialogDescription>Redacta un aviso para toda la comunidad.</DialogDescription>
                            </DialogHeader>
                            <form onSubmit={handlePostSubmit} className="space-y-4 py-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium text-slate-700 dark:text-slate-300">Título</label>
                                    <Input
                                        required
                                        value={newPost.title}
                                        onChange={(e) => setNewPost({ ...newPost, title: e.target.value })}
                                        placeholder="Ej: Mantención de Ascensores"
                                        className="input-premium"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium text-slate-700 dark:text-slate-300">Prioridad</label>
                                    <div className="grid grid-cols-3 gap-3">
                                        {['info', 'alert', 'event'].map((p) => {
                                            const styles = getPriorityStyles(p);
                                            const Icon = getIcon(p);
                                            return (
                                                <button
                                                    key={p}
                                                    type="button"
                                                    onClick={() => setNewPost({ ...newPost, priority: p })}
                                                    className={`p-3 rounded-xl border-2 transition-all ${newPost.priority === p
                                                        ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-500/10'
                                                        : 'border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600'
                                                        }`}
                                                >
                                                    <div className={`mx-auto w-8 h-8 rounded-lg ${styles.icon} flex items-center justify-center mb-2`}>
                                                        <Icon className="h-4 w-4" />
                                                    </div>
                                                    <p className="text-xs font-medium text-slate-700 dark:text-slate-300 text-center">{getPriorityLabel(p)}</p>
                                                </button>
                                            );
                                        })}
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium text-slate-700 dark:text-slate-300">Contenido</label>
                                    <textarea
                                        className="w-full min-h-[120px] rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 px-4 py-3 text-sm text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all"
                                        required
                                        value={newPost.content}
                                        onChange={(e) => setNewPost({ ...newPost, content: e.target.value })}
                                        placeholder="Escribe el detalle del comunicado..."
                                    />
                                </div>
                                <DialogFooter>
                                    <Button type="submit">Publicar</Button>
                                </DialogFooter>
                            </form>
                        </DialogContent>
                    </Dialog>
                )}
            </div>

            {/* Announcements List */}
            <div className="space-y-4">
                {isLoading ? (
                    <div className="space-y-4">
                        {[1, 2, 3].map((i) => (
                            <SkeletonAnnouncement key={i} />
                        ))}
                    </div>
                ) : (
                    <>
                        {announcements.map((ann, idx) => {
                            const styles = getPriorityStyles(ann.priority);
                            const Icon = getIcon(ann.priority);

                            return (
                                <article
                                    key={ann.id}
                                    className={`group relative overflow-hidden rounded-2xl bg-white dark:bg-slate-800 border-l-4 ${styles.border} shadow-lg dark:shadow-slate-950/50 ${styles.glow} hover:shadow-xl transition-all duration-300 animate-slide-up opacity-0`}
                                    style={{ animationDelay: `${idx * 0.1}s`, animationFillMode: 'forwards' }}
                                >
                                    <div className="p-6">
                                        <div className="flex items-start justify-between gap-4">
                                            <div className="flex items-start gap-4">
                                                <div className={`flex-shrink-0 p-3 rounded-xl ${styles.icon}`}>
                                                    <Icon className="h-5 w-5" />
                                                </div>
                                                <div className="min-w-0">
                                                    <h2 className="text-lg font-bold text-slate-900 dark:text-white group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">
                                                        {ann.title}
                                                    </h2>
                                                    <div className="flex items-center gap-2 mt-1 text-sm text-slate-500 dark:text-slate-400">
                                                        <span className="font-medium">{ann.author}</span>
                                                        <span>•</span>
                                                        <span>{getRelativeTime(ann.createdAt)}</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <span className={`flex-shrink-0 px-3 py-1 text-xs font-semibold rounded-full ring-1 ring-inset ${styles.badge}`}>
                                                {getPriorityLabel(ann.priority)}
                                            </span>
                                        </div>
                                        <p className="mt-4 text-slate-600 dark:text-slate-400 leading-relaxed whitespace-pre-wrap pl-16">
                                            {ann.content}
                                        </p>
                                    </div>
                                    <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-gradient-to-r from-transparent via-indigo-500/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                                </article>
                            );
                        })}

                        {announcements.length === 0 && (
                            <div className="text-center py-16 bg-white dark:bg-slate-800 rounded-2xl shadow-lg">
                                <Bell className="mx-auto h-12 w-12 text-slate-300 dark:text-slate-600 mb-4" />
                                <p className="text-slate-500 dark:text-slate-400">No hay avisos recientes.</p>
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
    );
}

