"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/lib/authContext";
import { serviceRequestsService } from "@/lib/services/providersService";
import { motion, AnimatePresence } from "framer-motion";
import {
    Wrench, Clock, CheckCircle2, XCircle, AlertCircle,
    ArrowLeft, Calendar, Phone, ChevronRight, MessageSquare
} from "lucide-react";
import Link from "next/link";
import { SkeletonList } from "@/components/ui/Skeleton";

export default function MyRequestsPage() {
    const { user } = useAuth();
    const [requests, setRequests] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            fetchRequests();
        }
    }, [user]);

    const fetchRequests = async () => {
        try {
            setLoading(true);
            const data = await serviceRequestsService.getByUser(user!.id);
            setRequests(data);
        } catch (error) {
            console.error("Error fetching requests:", error);
        } finally {
            setLoading(false);
        }
    };

    const getStatusConfig = (status: string) => {
        switch (status) {
            case 'pending':
                return {
                    label: 'Pendiente',
                    icon: Clock,
                    color: 'text-amber-600 dark:text-amber-400',
                    bg: 'bg-amber-50 dark:bg-amber-500/10',
                    border: 'border-amber-100 dark:border-amber-500/20'
                };
            case 'accepted':
                return {
                    label: 'En Camino',
                    icon: Wrench,
                    color: 'text-blue-600 dark:text-blue-400',
                    bg: 'bg-blue-50 dark:bg-blue-500/10',
                    border: 'border-blue-100 dark:border-blue-500/20'
                };
            case 'completed':
                return {
                    label: 'Completado',
                    icon: CheckCircle2,
                    color: 'text-emerald-600 dark:text-emerald-400',
                    bg: 'bg-emerald-50 dark:bg-emerald-500/10',
                    border: 'border-emerald-100 dark:border-emerald-500/20'
                };
            case 'cancelled':
                return {
                    label: 'Cancelado',
                    icon: XCircle,
                    color: 'text-rose-600 dark:text-rose-400',
                    bg: 'bg-rose-50 dark:bg-rose-500/10',
                    border: 'border-rose-100 dark:border-rose-500/20'
                };
            default:
                return {
                    label: status,
                    icon: AlertCircle,
                    color: 'text-slate-600 dark:text-slate-400',
                    bg: 'bg-slate-50 dark:bg-slate-500/10',
                    border: 'border-slate-100 dark:border-slate-500/20'
                };
        }
    };

    if (!user) return null;

    return (
        <div className="max-w-5xl mx-auto space-y-8">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <div className="flex items-center gap-2 text-slate-500 dark:text-slate-400 mb-2">
                        <Link href="/services" className="hover:text-blue-600 transition-colors">Servicios</Link>
                        <ChevronRight className="h-4 w-4" />
                        <span className="text-slate-900 dark:text-white font-medium">Mis Solicitudes</span>
                    </div>
                    <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Gestión de Solicitudes</h1>
                    <p className="text-slate-500 dark:text-slate-400 mt-1">Sigue el estado de tus pedidos técnicos y servicios.</p>
                </div>
                <Link
                    href="/services"
                    className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-semibold border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-all shadow-sm"
                >
                    <ArrowLeft className="h-4 w-4" />
                    Volver a Catálogo
                </Link>
            </div>

            {/* List Section */}
            <div className="space-y-4">
                {loading ? (
                    <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-lg border border-slate-100 dark:border-slate-700">
                        <SkeletonList count={3} />
                    </div>
                ) : requests.length > 0 ? (
                    <div className="grid gap-4">
                        <AnimatePresence>
                            {requests.map((request, idx) => {
                                const status = getStatusConfig(request.status);
                                const StatusIcon = status.icon;

                                return (
                                    <motion.div
                                        key={request.id}
                                        initial={{ opacity: 0, y: 20 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        transition={{ delay: idx * 0.05 }}
                                        className="group bg-white dark:bg-slate-800 rounded-2xl p-5 md:p-6 shadow-lg shadow-slate-200/50 dark:shadow-slate-950/50 border border-slate-100 dark:border-slate-700 hover:border-blue-200 dark:hover:border-blue-900/50 transition-all"
                                    >
                                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                                            <div className="flex items-start gap-4">
                                                <div className={`p-3 rounded-xl ${status.bg} ${status.color}`}>
                                                    <StatusIcon className="h-6 w-6" />
                                                </div>
                                                <div className="space-y-1">
                                                    <div className="flex items-center gap-2">
                                                        <h3 className="font-bold text-lg text-slate-900 dark:text-white">
                                                            {request.service_providers?.name || "Técnico"}
                                                        </h3>
                                                        <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold border ${status.bg} ${status.color} ${status.border}`}>
                                                            {status.label}
                                                        </span>
                                                    </div>
                                                    <p className="text-sm text-slate-500 dark:text-slate-400 line-clamp-1 max-w-md">
                                                        {request.description}
                                                    </p>
                                                    <div className="flex flex-wrap items-center gap-x-4 gap-y-1 pt-2">
                                                        <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
                                                            <Calendar className="h-3.5 w-3.5" />
                                                            {new Date(request.preferred_date).toLocaleDateString('es-CL', { day: 'numeric', month: 'short' })} a las {request.preferred_time}
                                                        </div>
                                                        <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
                                                            <MessageSquare className="h-3.5 w-3.5" />
                                                            Solicitado el {new Date(request.created_at).toLocaleDateString('es-CL')}
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex items-center gap-3">
                                                {request.service_providers?.contact_phone && (
                                                    <a
                                                        href={`tel:${request.service_providers.contact_phone}`}
                                                        className="flex-1 md:flex-none inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-slate-50 dark:bg-slate-700/50 text-slate-700 dark:text-slate-200 font-semibold border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-700 transition-all"
                                                    >
                                                        <Phone className="h-4 w-4" />
                                                        <span className="md:hidden lg:inline">Llamar</span>
                                                    </a>
                                                )}
                                                <Link
                                                    href={`/services/provider/${request.provider_id}`}
                                                    className="flex-1 md:flex-none inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-blue-600 text-white font-semibold shadow-lg shadow-blue-500/25 hover:bg-blue-700 transition-all"
                                                >
                                                    Ver Perfil
                                                </Link>
                                            </div>
                                        </div>
                                    </motion.div>
                                );
                            })}
                        </AnimatePresence>
                    </div>
                ) : (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        className="bg-white dark:bg-slate-800 rounded-3xl p-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-700"
                    >
                        <div className="mx-auto w-20 h-20 rounded-2xl bg-slate-100 dark:bg-slate-700/50 flex items-center justify-center mb-6">
                            <Wrench className="h-10 w-10 text-slate-400" />
                        </div>
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">No tienes solicitudes activas</h3>
                        <p className="text-slate-500 dark:text-slate-400 mb-8 max-w-sm mx-auto">
                            Cuando solicites un servicio a un técnico de la comunidad, aparecerá aquí para que puedas darle seguimiento.
                        </p>
                        <Link
                            href="/services"
                            className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-gradient-to-r from-blue-500 to-cyan-600 text-white font-bold shadow-lg shadow-blue-500/25 hover:shadow-xl hover:-translate-y-0.5 transition-all"
                        >
                            Explorar Catálogo de Servicios
                        </Link>
                    </motion.div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from 'react';
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { ArrowLeft, Upload, CheckCircle2 } from "lucide-react";
import Link from "next/link";
import { useToast } from "@/components/ui/Toast";
import { useRouter } from "next/navigation";

export default function ProviderRegisterPage() {
    const router = useRouter();
    const { toast } = useToast();
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState({
        // Basic Info
        name: '',
        email: '',
        phone: '',
        category: 'plumbing' as const,

        // Professional Info
        yearsExperience: '',
        bio: '',
        hourlyRate: '',
        responseTime: '< 2 horas',

        // Specialties
        specialties: [] as string[],
        newSpecialty: '',

        // Certifications
        certifications: [] as string[],
        newCertification: ''
    });

    const handleAddSpecialty = () => {
        if (formData.newSpecialty.trim()) {
            setFormData({
                ...formData,
                specialties: [...formData.specialties, formData.newSpecialty.trim()],
                newSpecialty: ''
            });
        }
    };

    const handleRemoveSpecialty = (index: number) => {
        setFormData({
            ...formData,
            specialties: formData.specialties.filter((_, i) => i !== index)
        });
    };

    const handleAddCertification = () => {
        if (formData.newCertification.trim()) {
            setFormData({
                ...formData,
                certifications: [...formData.certifications, formData.newCertification.trim()],
                newCertification: ''
            });
        }
    };

    const handleRemoveCertification = (index: number) => {
        setFormData({
            ...formData,
            certifications: formData.certifications.filter((_, i) => i !== index)
        });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        // Simple client-side mock submission for now
        // In production, this would make an API call to create the provider
        const providerData = {
            name: formData.name,
            category: formData.category,
            contactPhone: formData.phone,
            email: formData.email,
            bio: formData.bio,
            yearsExperience: parseInt(formData.yearsExperience),
            specialties: formData.specialties,
            certifications: formData.certifications,
            hourlyRate: parseFloat(formData.hourlyRate) || 0,
        };

        try {
            const response = await fetch('/api/providers', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(providerData),
            });

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.error || 'Error al registrar técnico');
            }

            toast({
                title: "¡Registro Exitoso!",
                description: "Tu perfil de técnico ha sido creado correctamente.",
                variant: "success",
            });

            // Redirect to the provider profile
            router.push(`/services/provider/${data.id}`);
        } catch (error: any) {
            toast({
                title: "Error",
                description: error.message || "No se pudo completar el registro. Intenta nuevamente.",
                variant: "destructive",
            });
        }
    };

    const getCategoryLabel = (cat: string) => {
        const labels = {
            plumbing: 'Gasfitería',
            electrical: 'Electricidad',
            locksmith: 'Cerrajería'
        };
        return labels[cat as keyof typeof labels] || cat;
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6">
            {/* Back Button */}
            <Link
                href="/services"
                className="inline-flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
            >
                <ArrowLeft className="h-4 w-4" />
                Volver a Servicios
            </Link>

            {/* Header */}
            <div className="text-center space-y-3">
                <h1 className="text-4xl font-bold text-slate-900 dark:text-white">
                    Regístrate como <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-cyan-600">Técnico Profesional</span>
                </h1>
                <p className="text-lg text-slate-500 dark:text-slate-400 max-w-2xl mx-auto">
                    Une a nuestra plataforma y conecta con cientos de clientes potenciales
                </p>
            </div>

            {/* Progress Steps */}
            <div className="flex items-center justify-center gap-4 mb-8">
                {[1, 2, 3].map((s) => (
                    <div key={s} className="flex items-center gap-2">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold transition-all ${s === step
                            ? 'bg-gradient-to-r from-blue-500 to-cyan-600 text-white shadow-lg'
                            : s < step
                                ? 'bg-emerald-500 text-white'
                                : 'bg-slate-200 dark:bg-slate-700 text-slate-400'
                            }`}>
                            {s < step ? <CheckCircle2 className="h-5 w-5" /> : s}
                        </div>
                        {s < 3 && (
                            <div className={`w-16 h-1 rounded-full ${s < step ? 'bg-emerald-500' : 'bg-slate-200 dark:bg-slate-700'}`} />
                        )}
                    </div>
                ))}
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-100 dark:border-slate-700 p-8">
                {/* Step 1: Basic Info */}
                {step === 1 && (
                    <div className="space-y-6">
                        <div>
                            <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-6">Información Básica</h2>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                Nombre Completo *
                            </label>
                            <Input
                                required
                                value={formData.name}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                placeholder="Juan Pérez"
                            />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                    Email *
                                </label>
                                <Input
                                    type="email"
                                    required
                                    value={formData.email}
                                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                    placeholder="juan@ejemplo.cl"
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                    Teléfono *
                                </label>
                                <Input
                                    type="tel"
                                    required
                                    value={formData.phone}
                                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                                    placeholder="+56 9 1234 5678"
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                Categoría Principal *
                            </label>
                            <select
                                required
                                value={formData.category}
                                onChange={(e) => setFormData({ ...formData, category: e.target.value as any })}
                                className="w-full px-4 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                            >
                                <option value="plumbing">Gasfitería</option>
                                <option value="electrical">Electricidad</option>
                                <option value="locksmith">Cerrajería</option>
                            </select>
                        </div>

                        <div className="flex justify-end pt-4">
                            <Button
                                type="button"
                                onClick={() => setStep(2)}
                            >
                                Siguiente
                            </Button>
                        </div>
                    </div>
                )}

                {/* Step 2: Professional Info */}
                {step === 2 && (
                    <div className="space-y-6">
                        <div>
                            <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-6">Información Profesional</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                    Años de Experiencia *
                                </label>
                                <Input
                                    type="number"
                                    required
                                    min="0"
                                    value={formData.yearsExperience}
                                    onChange={(e) => setFormData({ ...formData, yearsExperience: e.target.value })}
                                    placeholder="10"
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                    Tarifa por Hora (CLP)
                                </label>
                                <Input
                                    type="number"
                                    min="0"
                                    value={formData.hourlyRate}
                                    onChange={(e) => setFormData({ ...formData, hourlyRate: e.target.value })}
                                    placeholder="15000"
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                Tiempo de Respuesta *
                            </label>
                            <select
                                required
                                value={formData.responseTime}
                                onChange={(e) => setFormData({ ...formData, responseTime: e.target.value })}
                                className="w-full px-4 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                            >
                                <option value="< 30 minutos">Menos de 30 minutos</option>
                                <option value="< 1 hora">Menos de 1 hora</option>
                                <option value="< 2 horas">Menos de 2 horas</option>
                                <option value="< 4 horas">Menos de 4 horas</option>
                                <option value="< 24 horas">Menos de 24 horas</option>
                            </select>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                Sobre Ti (Biografía) *
                            </label>
                            <textarea
                                required
                                className="w-full min-h-[120px] rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                                placeholder="Cuenta sobre tu experiencia, especialidades y qué te hace único..."
                                value={formData.bio}
                                onChange={(e) => setFormData({ ...formData, bio: e.target.value })}
                            />
                        </div>

                        <div className="flex justify-between pt-4">
                            <Button
                                type="button"
                                variant="outline"
                                onClick={() => setStep(1)}
                            >
                                Atrás
                            </Button>
                            <Button
                                type="button"
                                onClick={() => setStep(3)}
                            >
                                Siguiente
                            </Button>
                        </div>
                    </div>
                )}

                {/* Step 3: Specialties & Certifications */}
                {step === 3 && (
                    <div className="space-y-6">
                        <div>
                            <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-6">Especialidades y Certificaciones</h2>
                        </div>

                        {/* Specialties */}
                        <div className="space-y-3">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                Especialidades *
                            </label>
                            <div className="flex gap-2">
                                <Input
                                    value={formData.newSpecialty}
                                    onChange={(e) => setFormData({ ...formData, newSpecialty: e.target.value })}
                                    placeholder="Ej: Reparación de cañerías"
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            handleAddSpecialty();
                                        }
                                    }}
                                />
                                <Button type="button" variant="outline" onClick={handleAddSpecialty}>
                                    Agregar
                                </Button>
                            </div>
                            {formData.specialties.length > 0 && (
                                <div className="flex flex-wrap gap-2 mt-3">
                                    {formData.specialties.map((specialty, idx) => (
                                        <span
                                            key={idx}
                                            className="inline-flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-500/10 text-blue-700 dark:text-blue-400 rounded-lg text-sm border border-blue-100 dark:border-blue-500/20"
                                        >
                                            {specialty}
                                            <button
                                                type="button"
                                                onClick={() => handleRemoveSpecialty(idx)}
                                                className="hover:text-blue-900 dark:hover:text-blue-300"
                                            >
                                                ×
                                            </button>
                                        </span>
                                    ))}
                                </div>
                            )}
                        </div>

                        {/* Certifications */}
                        <div className="space-y-3">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                Certificaciones
                            </label>
                            <div className="flex gap-2">
                                <Input
                                    value={formData.newCertification}
                                    onChange={(e) => setFormData({ ...formData, newCertification: e.target.value })}
                                    placeholder="Ej: Certificación SEC Clase A"
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            handleAddCertification();
                                        }
                                    }}
                                />
                                <Button type="button" variant="outline" onClick={handleAddCertification}>
                                    Agregar
                                </Button>
                            </div>
                            {formData.certifications.length > 0 && (
                                <div className="flex flex-wrap gap-2 mt-3">
                                    {formData.certifications.map((cert, idx) => (
                                        <span
                                            key={idx}
                                            className="inline-flex items-center gap-2 px-3 py-1.5 bg-amber-50 dark:bg-amber-500/10 text-amber-700 dark:text-amber-400 rounded-lg text-sm border border-amber-100 dark:border-amber-500/20"
                                        >
                                            {cert}
                                            <button
                                                type="button"
                                                onClick={() => handleRemoveCertification(idx)}
                                                className="hover:text-amber-900 dark:hover:text-amber-300"
                                            >
                                                ×
                                            </button>
                                        </span>
                                    ))}
                                </div>
                            )}
                        </div>

                        {/* Photo Upload Placeholder */}
                        <div className="space-y-3">
                            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                Foto de Perfil
                            </label>
                            <div className="border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-xl p-8 text-center hover:border-blue-500 dark:hover:border-blue-500 transition-colors cursor-pointer">
                                <Upload className="h-12 w-12 mx-auto mb-3 text-slate-400" />
                                <p className="text-sm text-slate-600 dark:text-slate-400">
                                    Haz clic para subir una foto o arrastra aquí
                                </p>
                                <p className="text-xs text-slate-400 dark:text-slate-500 mt-1">
                                    JPG, PNG hasta 5MB
                                </p>
                            </div>
                        </div>

                        <div className="flex justify-between pt-4">
                            <Button
                                type="button"
                                variant="outline"
                                onClick={() => setStep(2)}
                            >
                                Atrás
                            </Button>
                            <Button
                                type="submit"
                                disabled={formData.specialties.length === 0}
                            >
                                Enviar Solicitud
                            </Button>
                        </div>
                    </div>
                )}
            </form>

            {/* Info Box */}
            <div className="bg-blue-50 dark:bg-blue-500/10 border border-blue-100 dark:border-blue-500/20 rounded-xl p-6">
                <h3 className="font-semibold text-blue-900 dark:text-blue-400 mb-2">¿Qué sigue después del registro?</h3>
                <ul className="space-y-2 text-sm text-blue-800 dark:text-blue-300">
                    <li className="flex items-start gap-2">
                        <CheckCircle2 className="h-5 w-5 flex-shrink-0 mt-0.5" />
                        <span>Revisaremos tu perfil en 24-48 horas</span>
                    </li>
                    <li className="flex items-start gap-2">
                        <CheckCircle2 className="h-5 w-5 flex-shrink-0 mt-0.5" />
                        <span>Te contactaremos para verificar tus certificaciones</span>
                    </li>
                    <li className="flex items-start gap-2">
                        <CheckCircle2 className="h-5 w-5 flex-shrink-0 mt-0.5" />
                        <span>Una vez aprobado, tu perfil estará visible para clientes</span>
                    </li>
                </ul>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useAuth } from "@/lib/authContext";
import { SocialService } from "@/lib/services/supabaseServices";
import { SocialPost, SocialComment } from "@/lib/types";
import { supabase } from "@/lib/supabase";
import { motion, AnimatePresence } from "framer-motion";
import { useToast } from "@/components/ui/Toast";
import { Button } from "@/components/ui/Button";
import { SkeletonCard } from "@/components/ui/Skeleton";
import {
    Heart, MessageCircle, Share2, MoreHorizontal,
    Image as ImageIcon, Send, Smile, MapPin, Hash,
    Loader2, X as XIcon
} from "lucide-react";
import clsx from "clsx";

export default function SocialFeedPage() {
    const { user } = useAuth();
    const { toast } = useToast();

    const [posts, setPosts] = useState<SocialPost[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // New Post Form
    const [newPostContent, setNewPostContent] = useState("");
    const [newPostImageFile, setNewPostImageFile] = useState<File | null>(null);
    const [newPostImagePreview, setNewPostImagePreview] = useState<string | null>(null);
    const [isUploadingImage, setIsUploadingImage] = useState(false);
    const imageInputRef = useRef<HTMLInputElement>(null);

    // Comments State View
    const [activeCommentPostId, setActiveCommentPostId] = useState<string | null>(null);
    const [comments, setComments] = useState<Record<string, SocialComment[]>>({});
    const [newCommentContent, setNewCommentContent] = useState("");
    const [loadingCommentsPostId, setLoadingCommentsPostId] = useState<string | null>(null);

    useEffect(() => {
        loadPosts();
    }, []);

    const loadPosts = async () => {
        setIsLoading(true);
        try {
            const data = await SocialService.getPosts();
            if (data) setPosts(data as unknown as SocialPost[]);
        } catch (error) {
            console.error("Error loading social posts:", error);
            setPosts([]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setNewPostImageFile(file);
        setNewPostImagePreview(URL.createObjectURL(file));
    };

    const handleCreatePost = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user || (!newPostContent.trim() && !newPostImageFile)) return;

        setIsSubmitting(true);
        let imageUrl: string | undefined;

        // Upload image to Supabase Storage if provided
        if (newPostImageFile) {
            setIsUploadingImage(true);
            try {
                const ext = newPostImageFile.name.split('.').pop();
                const path = `posts/${user.id}/${Date.now()}.${ext}`;
                const { error: uploadError } = await supabase.storage
                    .from('social-images')
                    .upload(path, newPostImageFile, { upsert: false });
                if (!uploadError) {
                    const { data: { publicUrl } } = supabase.storage
                        .from('social-images')
                        .getPublicUrl(path);
                    imageUrl = publicUrl;
                }
            } catch (err) {
                console.error('Image upload failed:', err);
            } finally {
                setIsUploadingImage(false);
            }
        }

        try {
            const newPost = await SocialService.createPost({
                author_id: user.id,
                content: newPostContent.trim(),
                image_url: imageUrl
            });

            setPosts([newPost as unknown as SocialPost, ...posts]);
            setNewPostContent("");
            setNewPostImageFile(null);
            setNewPostImagePreview(null);

            toast({
                title: "Publicado",
                description: "Tu publicación ya está visible en el muro.",
                variant: "success"
            });
        } catch (error) {
            toast({ title: "Error", description: "Hubo un problema al publicar.", variant: "destructive" });
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleLike = async (postId: string) => {
        try {
            // Optimistic Update
            setPosts(prev => prev.map((p: any) => {
                if (p.id === postId) {
                    return { ...p, likes_count: p.likes_count + 1, has_liked: true };
                }
                return p;
            }));
            await SocialService.likePost(postId);
        } catch (error) {
            // Revert on error
            setPosts(prev => prev.map((p: any) => {
                if (p.id === postId) {
                    return { ...p, likes_count: p.likes_count - 1, has_liked: false };
                }
                return p;
            }));
            toast({ title: "Error", description: "No se pudo dar like.", variant: "destructive" });
        }
    };

    const toggleComments = async (postId: string) => {
        if (activeCommentPostId === postId) {
            setActiveCommentPostId(null);
            return;
        }

        setActiveCommentPostId(postId);

        // Load Comments if not already loaded into dictionary
        if (!comments[postId]) {
            setLoadingCommentsPostId(postId);
            try {
                const data = await SocialService.getComments(postId);
                setComments(prev => ({ ...prev, [postId]: data }));
            } catch (error) {
                console.error("Error loading comments", error);
            } finally {
                setLoadingCommentsPostId(null);
            }
        }
    };

    const handleCreateComment = async (e: React.FormEvent, postId: string) => {
        e.preventDefault();
        if (!user || !newCommentContent.trim()) return;

        try {
            const comment = await SocialService.createComment({
                post_id: postId,
                author_id: user.id,
                content: newCommentContent.trim()
            });

            // Update comments locally
            setComments(prev => ({
                ...prev,
                [postId]: [...(prev[postId] || []), comment]
            }));

            // Increment comment count on Post summary
            setPosts(prev => prev.map((p: any) => p.id === postId ? { ...p, comments_count: (p.comments_count || 0) + 1 } : p));
            setNewCommentContent("");

        } catch (error) {
            toast({ title: "Error", description: "No se pudo enviar el comentario", variant: "destructive" });
        }
    };

    return (
        <div className="max-w-3xl mx-auto py-10 px-4 sm:px-6 space-y-10">
            {/* Header */}
            <div className="flex items-center gap-4">
                <div className="p-3 bg-gradient-to-br from-fuchsia-500 to-pink-600 rounded-2xl shadow-lg shadow-fuchsia-500/30">
                    <Hash className="h-6 w-6 text-white" />
                </div>
                <div>
                    <h1 className="text-3xl font-black text-slate-900 dark:text-white">Muro Social</h1>
                    <p className="text-sm font-medium text-slate-500 mt-1">Comparte novedades, datos y fotos con tus vecinos.</p>
                </div>
            </div>

            {/* Create Post Field */}
            <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-6 sm:p-8 border border-slate-100 dark:border-slate-800 shadow-xl shadow-slate-200/20 dark:shadow-none transition-all hover:shadow-2xl">
                <form onSubmit={handleCreatePost}>
                    <div className="flex gap-4 sm:gap-6">
                        <div className="w-12 h-12 rounded-full overflow-hidden bg-gradient-to-br from-indigo-500 to-purple-500 flex-shrink-0 border-2 border-white dark:border-slate-800 shadow-md">
                            {user?.photo ? (
                                <img src={user.photo} alt={user.name} className="w-full h-full object-cover" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-white font-black text-lg">
                                    {user?.name.charAt(0)}
                                </div>
                            )}
                        </div>
                        <div className="flex-1 space-y-4">
                            <textarea
                                value={newPostContent}
                                onChange={(e) => setNewPostContent(e.target.value)}
                                placeholder="¿Qué está pasando en el edificio?"
                                className="w-full min-h-[100px] resize-none bg-transparent text-lg font-medium text-slate-900 dark:text-white placeholder:text-slate-400 focus:outline-none"
                            />

                            {/* Actions Footer */}
                            <div className="flex items-center justify-between pt-4 border-t border-slate-100 dark:border-slate-800">
                                <div className="flex gap-2">
                                    <button
                                        type="button"
                                        onClick={() => imageInputRef.current?.click()}
                                        className="p-2 text-slate-400 hover:text-fuchsia-500 hover:bg-fuchsia-50 dark:hover:bg-fuchsia-500/10 rounded-full transition-colors"
                                        title="Añadir Foto"
                                    >
                                        {isUploadingImage ? <Loader2 className="h-5 w-5 animate-spin" /> : <ImageIcon className="h-5 w-5" />}
                                    </button>
                                    <input ref={imageInputRef} type="file" accept="image/*" className="hidden" onChange={handleImageSelect} />
                                    <button type="button" className="p-2 text-slate-400 hover:text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-500/10 rounded-full transition-colors hidden sm:block">
                                        <Smile className="h-5 w-5" />
                                    </button>
                                    <button type="button" className="p-2 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-500/10 rounded-full transition-colors hidden sm:block">
                                        <MapPin className="h-5 w-5" />
                                    </button>
                                </div>
                                <Button
                                    type="submit"
                                    disabled={(!newPostContent.trim() && !newPostImageFile) || isSubmitting}
                                    className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-full px-6 font-bold shadow-lg hover:scale-105 transition-transform"
                                >
                                    {isSubmitting ? <Loader2 className="h-5 w-5 animate-spin" /> : 'Publicar'}
                                </Button>
                            </div>

                            {/* Image Preview */}
                            {newPostImagePreview && (
                                <div className="relative mt-3 rounded-2xl overflow-hidden border border-slate-200 dark:border-slate-700">
                                    <img src={newPostImagePreview} alt="preview" className="w-full max-h-64 object-cover" />
                                    <button
                                        type="button"
                                        onClick={() => { setNewPostImageFile(null); setNewPostImagePreview(null); }}
                                        className="absolute top-2 right-2 p-1.5 bg-black/50 text-white rounded-full hover:bg-black/70 transition-colors"
                                    >
                                        <XIcon className="h-4 w-4" />
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </form>
            </div>

            {/* Feed Stream */}
            <div className="space-y-6">
                {isLoading && (
                    <>
                        <SkeletonCard />
                        <SkeletonCard />
                        <SkeletonCard />
                    </>
                )}

                {!isLoading && posts.length === 0 && (
                    <div className="bg-slate-50 dark:bg-slate-900/50 rounded-[3rem] border border-dashed border-slate-200 dark:border-slate-800 p-16 text-center space-y-4">
                        <MessageCircle className="h-16 w-16 text-slate-300 mx-auto" />
                        <h3 className="text-xl font-black text-slate-500">Nada por aquí aún</h3>
                        <p className="text-sm font-medium text-slate-400">Sé el primero en saludar a tus vecinos.</p>
                    </div>
                )}

                <AnimatePresence>
                    {posts.map((post: any) => (
                        <motion.div
                            key={post.id}
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            className="bg-white dark:bg-slate-900 flex flex-col rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-lg shadow-slate-200/20 dark:shadow-none overflow-hidden"
                        >
                            {/* Post Header */}
                            <div className="p-6 sm:p-8 pb-4 flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-full overflow-hidden bg-slate-200 dark:bg-slate-800">
                                        {post.profiles?.avatar_url ? (
                                            <img src={post.profiles.avatar_url} alt="avatar" className="w-full h-full object-cover" />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center font-black text-slate-400">
                                                {post.profiles?.name?.charAt(0) || '?'}
                                            </div>
                                        )}
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-slate-900 dark:text-white flex items-center gap-2">
                                            {post.profiles?.name || 'Residente'}
                                            {post.profiles?.unit_id && (
                                                <span className="text-[10px] font-black uppercase text-slate-400 tracking-wider bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full">
                                                    Depto {post.profiles.unit_id}
                                                </span>
                                            )}
                                        </h3>
                                        <p className="text-xs font-semibold text-slate-400 mt-0.5">
                                            {new Date(post.created_at).toLocaleDateString()} a las {new Date(post.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </p>
                                    </div>
                                </div>
                                <button className="p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors">
                                    <MoreHorizontal className="h-5 w-5" />
                                </button>
                            </div>

                            {/* Post Body */}
                            <div className="px-6 sm:px-8 py-2">
                                <p className="text-slate-800 dark:text-slate-200 text-base leading-relaxed whitespace-pre-line">
                                    {post.content}
                                </p>
                                {post.image_url && (
                                    <div className="mt-4 rounded-2xl overflow-hidden border border-slate-100 dark:border-slate-800">
                                        <img src={post.image_url} alt="post image" className="w-full h-auto object-cover max-h-[500px]" />
                                    </div>
                                )}
                            </div>

                            {/* Interaction Bar */}
                            <div className="px-6 sm:px-8 py-4 mt-2 border-t border-slate-50 dark:border-slate-800/50 flex items-center gap-6">
                                <button
                                    onClick={() => handleLike(post.id)}
                                    className={clsx(
                                        "flex items-center gap-2 group transition-colors",
                                        post.has_liked ? "text-rose-500" : "text-slate-400 hover:text-rose-500"
                                    )}
                                >
                                    <div className={clsx("p-2 rounded-full transition-all flex items-center justify-center", post.has_liked ? "bg-rose-50 dark:bg-rose-500/10" : "group-hover:bg-rose-50 dark:group-hover:bg-rose-500/10")}>
                                        <Heart className={clsx("h-5 w-5", post.has_liked && "fill-current")} />
                                    </div>
                                    <span className="font-bold">{post.likes_count > 0 ? post.likes_count : 'Me gusta'}</span>
                                </button>

                                <button
                                    onClick={() => toggleComments(post.id)}
                                    className="flex items-center gap-2 text-slate-400 hover:text-blue-500 group transition-colors"
                                >
                                    <div className="p-2 rounded-full transition-all flex items-center justify-center group-hover:bg-blue-50 dark:group-hover:bg-blue-500/10">
                                        <MessageCircle className="h-5 w-5" />
                                    </div>
                                    <span className="font-bold">{post.comments_count ? post.comments_count : 'Comentar'}</span>
                                </button>

                                <button className="flex items-center gap-2 text-slate-400 hover:text-emerald-500 group transition-colors ml-auto">
                                    <div className="p-2 rounded-full transition-all flex items-center justify-center group-hover:bg-emerald-50 dark:group-hover:bg-emerald-500/10">
                                        <Share2 className="h-5 w-5" />
                                    </div>
                                </button>
                            </div>

                            {/* Comments Section Dropdown */}
                            <AnimatePresence>
                                {activeCommentPostId === post.id && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: "auto", opacity: 1 }}
                                        exit={{ height: 0, opacity: 0 }}
                                        className="bg-slate-50 dark:bg-slate-800/30 border-t border-slate-100 dark:border-slate-800 overflow-hidden"
                                    >
                                        <div className="p-6 sm:p-8 space-y-6">
                                            {/* List of comments */}
                                            {loadingCommentsPostId === post.id ? (
                                                <div className="flex justify-center py-4"><Loader2 className="h-6 w-6 animate-spin text-slate-400" /></div>
                                            ) : (
                                                <div className="space-y-5">
                                                    {(comments[post.id] || []).map((comment: any) => (
                                                        <div key={comment.id} className="flex gap-4">
                                                            <div className="w-8 h-8 rounded-full overflow-hidden bg-slate-300 dark:bg-slate-700 flex-shrink-0">
                                                                {comment.profiles?.avatar_url ? (
                                                                    <img src={comment.profiles.avatar_url} alt="av" className="w-full h-full object-cover" />
                                                                ) : (
                                                                    <div className="w-full h-full flex items-center justify-center text-[10px] font-black text-slate-500">
                                                                        {comment.profiles?.name?.charAt(0) || '?'}
                                                                    </div>
                                                                )}
                                                            </div>
                                                            <div className="flex-1">
                                                                <div className="bg-white dark:bg-slate-800 px-4 py-3 rounded-2xl rounded-tl-none border border-slate-200 dark:border-slate-700 inline-block">
                                                                    <p className="text-xs font-black text-slate-900 dark:text-white mb-0.5">{comment.profiles?.name}</p>
                                                                    <p className="text-sm font-medium text-slate-700 dark:text-slate-300">{comment.content}</p>
                                                                </div>
                                                                <p className="text-[10px] font-bold text-slate-400 mt-1 ml-2">
                                                                    {new Date(comment.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                                </p>
                                                            </div>
                                                        </div>
                                                    ))}
                                                    {(comments[post.id] || []).length === 0 && (
                                                        <p className="text-xs font-bold text-center text-slate-400">Sé el primero en comentar.</p>
                                                    )}
                                                </div>
                                            )}

                                            {/* Add Comment */}
                                            <div className="flex gap-3 pt-2">
                                                <div className="w-8 h-8 rounded-full overflow-hidden bg-slate-300 flex-shrink-0 hidden sm:block">
                                                    {user?.photo ? (
                                                        <img src={user.photo} alt="U" className="w-full h-full object-cover" />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center text-[10px] font-black text-white bg-slate-400">
                                                            {user?.name.charAt(0)}
                                                        </div>
                                                    )}
                                                </div>
                                                <form
                                                    className="flex-1 relative"
                                                    onSubmit={(e) => handleCreateComment(e, post.id)}
                                                >
                                                    <input
                                                        type="text"
                                                        placeholder="Escribe un comentario..."
                                                        className="w-full h-10 pl-4 pr-12 rounded-full border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                                                        value={newCommentContent}
                                                        onChange={(e) => setNewCommentContent(e.target.value)}
                                                    />
                                                    <button
                                                        type="submit"
                                                        disabled={!newCommentContent.trim()}
                                                        className="absolute right-1 top-1 w-8 h-8 flex items-center justify-center bg-blue-500 text-white rounded-full disabled:opacity-50 disabled:bg-slate-300 transition-all hover:scale-105"
                                                    >
                                                        <Send className="h-3.5 w-3.5" />
                                                    </button>
                                                </form>
                                            </div>
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </motion.div>
                    ))}
                </AnimatePresence>
            </div>
        </div>
    );
}

