export async function POST(req: Request) {
    try {
        const supabase = await getSupabase();

        // Ensure user is authenticated
        const { data: { user }, error: authError } = await supabase.auth.getUser();
        if (authError || !user) {
            return NextResponse.json({ error: "No autorizado" }, { status: 401 });
        }

        // Obtener el community_id y verificar si es administrador
        const { data: profile } = await supabase
            .from('profiles')
            .select('role, community_id')
            .eq('id', user.id)
            .single();

        if (!profile || profile.role !== 'admin') {
            return NextResponse.json({ error: "Permisos insuficientes o no es administrador." }, { status: 403 });
        }

        const body = await req.json();
        const { title, description, target_audience, content } = body;

        if (!title || !content) {
            return NextResponse.json({ error: "Título y contenido son obligatorios" }, { status: 400 });
        }

        // 1. Crear el módulo
        const { data: modData, error: modError } = await supabase
            .from('training_modules')
            .insert({ 
                title, 
                description: description || '',
                target_audience: target_audience || 'all',
                is_active: true
            })
            .select()
            .single();

        if (modError) {
            console.error("Supabase Error Details:", modError);
            throw new Error(`DB Error: ${modError.message} | Details: ${modError.details || 'n/a'} | Hint: ${modError.hint || 'n/a'}`);
        }

        // 2. Crear la lección asociada
        const { error: lessonError } = await supabase
            .from('training_lessons')
            .insert({
                module_id: modData.id,
                title: "Lección Principal",
                content,
                order_index: 0
            });

        if (lessonError) throw lessonError;

        return NextResponse.json({ success: true, module: modData });

    } catch (error: any) {
        console.error("Error creating module:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}

export async function DELETE(req: Request) {
    try {
        const supabase = await getSupabase();
        const url = new URL(req.url);
        const id = url.searchParams.get('id');

        if (!id) return NextResponse.json({ error: "No ID provided" }, { status: 400 });

        const { data, error } = await supabase
            .from('training_modules')
            .delete()
            .eq('id', id)
            .select();

        if (error) throw error;

        if (!data || data.length === 0) {
            return NextResponse.json({ 
                error: "El motor de base de datos denegó la eliminación (No tienes una política RLS de DELETE). Igual que con el INSERT anterior, debes correr esto en el SQL Editor de Supabase:\n\nCREATE POLICY \"Enable Delete for Modules\" ON public.training_modules FOR DELETE TO authenticated USING (true);" 
            }, { status: 403 });
        }
        return NextResponse.json({ success: true });
    } catch (error: any) {
        console.error("Error deleting module:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import { runMultiAgentTurn } from "@/lib/ai/orchestrator";

// Rate limiter implementation similar to CoCo
const rateLimitMap = new Map<string, { count: number; resetAt: number }>();
const RATE_LIMIT_MAX = 50;
const RATE_LIMIT_WINDOW = 60_000;

function checkRateLimit(ip: string): boolean {
    const now = Date.now();
    const entry = rateLimitMap.get(ip);
    if (!entry || now > entry.resetAt) {
        rateLimitMap.set(ip, { count: 1, resetAt: now + RATE_LIMIT_WINDOW });
        return true;
    }
    if (entry.count >= RATE_LIMIT_MAX) return false;
    entry.count++;
    return true;
}

export async function POST(req: NextRequest) {
    const GEMINI_API_KEY = (process.env.GEMINI_API_KEY || "").trim();

    const ip = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim()
        ?? req.headers.get("x-real-ip")
        ?? "unknown";

    if (!checkRateLimit(ip)) {
        return NextResponse.json(
            { error: "Too many messages" },
            { status: 429 }
        );
    }

    if (!GEMINI_API_KEY || !GEMINI_API_KEY.startsWith("AIza")) {
        return NextResponse.json({
            responses: [{
                id: `sys-err-${Date.now()}`,
                role: 'system',
                text: 'Error interno: La GEMINI_API_KEY no está configurada correctamente en el entorno.'
            }]
        }, { status: 200 });
    }

    try {
        const body = await req.json();
        const { message, history, courseContent } = body;

        if (!message) {
            return NextResponse.json({ error: "Message is required" }, { status: 400 });
        }

        // Call the orchestrator, passing the injected courseContent if available
        const responses = await runMultiAgentTurn(GEMINI_API_KEY, history || [], message, courseContent);

        return NextResponse.json({ responses }, { status: 200 });

    } catch (error: any) {
        console.error("Training MultiAgent API Error:", error);
        return NextResponse.json({
            responses: [{
                id: `sys-err-${Date.now()}`,
                role: 'system',
                text: `Error de los modelos de IA: ${error.message || "Desconocido"}. Revisa los logs o tu clave de API.`
            }]
        }, { status: 200 });
    }
}

import { NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';
export const maxDuration = 60; // Extender timeout a 60s en Vercel Hobby

export async function POST(request: Request) {
    try {
        const formData = await request.formData();
        const file = formData.get('file') as File;

        if (!file) {
            return NextResponse.json({ error: 'No se encontró un archivo en la solicitud' }, { status: 400 });
        }

        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);
        const fileName = file.name.toLowerCase();

        let extractedText = '';

        if (fileName.endsWith('.pdf')) {
            const apiKey = process.env.GEMINI_API_KEY;
            if (!apiKey) throw new Error("GEMINI_API_KEY no configurada. Imposible leer PDFs en Vercel.");

            const pdfBase64 = buffer.toString('base64');
            const inlineData = { mimeType: 'application/pdf', data: pdfBase64 };

            const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;
            const body = {
                contents: [{
                    role: "user", 
                    parts: [
                        { text: "Extrae TODO el texto de este documento de entrenamiento exactamente como está escrito, sin omitir partes, sin resumir y sin agregar comentarios extras. Solo retorna el contenido puro en texto plano directo, sin usar bloques de código Markdown." },
                        { inlineData }
                    ]
                }],
                generationConfig: { temperature: 0.1 }
            };

            const response = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
            if (!response.ok) throw new Error("Error al analizar PDF con IA: " + response.statusText);
            const data = await response.json();
            extractedText = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
        } else if (fileName.endsWith('.docx') || fileName.endsWith('.doc')) {
            // Extraer texto de Word evadiendo crash
            const mammoth = require('mammoth');
            const result = await mammoth.extractRawText({ buffer });
            extractedText = result.value;
        } else if (fileName.endsWith('.txt')) {
            // Leer TXT directamente
            extractedText = buffer.toString('utf-8');
        } else {
            return NextResponse.json({ 
                error: 'Formato de archivo no soportado. Por favor sube un PDF, Word (.docx) o TXT.' 
            }, { status: 400 });
        }

        // Limpieza básica del texto extraído
        const cleanedText = extractedText
            .replace(/\u0000/g, '') // Remove nulos
            .replace(/\n{3,}/g, '\n\n') // Reducir saltos de línea múltiples
            .trim();

        if (!cleanedText) {
            return NextResponse.json({ error: 'El documento parece estar vacío o contenía solo imágenes.' }, { status: 400 });
        }

        return NextResponse.json({ text: cleanedText });

    } catch (error: any) {
        console.error('Error parsing document:', error);
        return NextResponse.json({ 
            error: 'Ocurrió un error al procesar el archivo. ' + (error.message || '') 
        }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";

const supabaseAdmin = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

const TWILIO_ACCOUNT_SID = process.env.TWILIO_ACCOUNT_SID;
const TWILIO_AUTH_TOKEN = process.env.TWILIO_AUTH_TOKEN;
const TWILIO_FROM = process.env.TWILIO_WHATSAPP_FROM || "whatsapp:+14155238886"; // Twilio sandbox

// Format Chilean numbers: +569XXXXXXXX
function formatPhoneNumber(raw: string): string {
    const digits = raw.replace(/\D/g, "");
    if (digits.startsWith("569")) return `+${digits}`;
    if (digits.startsWith("9") && digits.length === 9) return `+56${digits}`;
    if (digits.startsWith("56")) return `+${digits}`;
    return `+${digits}`;
}

async function sendWhatsApp(to: string, message: string) {
    if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN) {
        throw new Error("Twilio credentials not configured");
    }

    const formattedTo = `whatsapp:${formatPhoneNumber(to)}`;
    const url = `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`;

    const params = new URLSearchParams({
        From: TWILIO_FROM,
        To: formattedTo,
        Body: message,
    });

    const res = await fetch(url, {
        method: "POST",
        headers: {
            "Content-Type": "application/x-www-form-urlencoded",
            Authorization: `Basic ${Buffer.from(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`).toString("base64")}`,
        },
        body: params.toString(),
    });

    if (!res.ok) {
        const err = await res.json();
        throw new Error(err.message || "Twilio error");
    }
    return res.json();
}

// POST /api/whatsapp-notify
// Called by Supabase Webhook OR directly from the app
// Body: { user_id, title, body, type }
export async function POST(req: NextRequest) {
    try {
        const { user_id, title, body: notifBody, type } = await req.json();

        if (!user_id || !title) {
            return NextResponse.json({ error: "Missing user_id or title" }, { status: 400 });
        }

        // Get user's phone number and WhatsApp opt-in status
        const { data: profile, error } = await supabaseAdmin
            .from("profiles")
            .select("phone_number, whatsapp_enabled, name")
            .eq("id", user_id)
            .single();

        if (error || !profile) {
            return NextResponse.json({ error: "Profile not found" }, { status: 404 });
        }

        if (!profile.whatsapp_enabled || !profile.phone_number) {
            return NextResponse.json({ skipped: true, reason: "WhatsApp not enabled or no phone number" });
        }

        // Build message
        const emoji = type === "alert" ? "🚨" : type === "success" ? "✅" : type === "warning" ? "⚠️" : "📢";
        const message = [
            `${emoji} *ComunidadConnect*`,
            ``,
            `*${title}*`,
            notifBody || "",
            ``,
            `👉 Revisa tu cuenta en la plataforma.`,
        ].join("\n");

        await sendWhatsApp(profile.phone_number, message);

        return NextResponse.json({ success: true, sentTo: profile.phone_number });
    } catch (err: any) {
        console.error("WhatsApp notify error:", err.message);
        return NextResponse.json({ error: err.message }, { status: 500 });
    }
}

