                        {/* Quick actions */}
                        {msgs.length === 1 && (
                            <div className="px-3 py-2 flex flex-wrap gap-1.5 bg-slate-50 dark:bg-slate-950 border-t border-pink-100 dark:border-slate-800 flex-shrink-0">
                                {QUICK.map(({ label, icon: Icon }) => (
                                    <button key={label} onClick={() => send(label)}
                                        className="flex items-center gap-1.5 px-2.5 py-1.5 bg-white dark:bg-slate-800 rounded-xl text-[11px] font-semibold text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:border-pink-300 hover:text-pink-600 transition-colors">
                                        <Icon className="h-3 w-3" />{label}
                                    </button>
                                ))}
                            </div>
                        )}

                        {/* Input */}
                        <div className="px-3 py-3 bg-white dark:bg-slate-900 border-t border-pink-100 dark:border-slate-800 flex-shrink-0">
                            <form onSubmit={e => { e.preventDefault(); send(input); }} className="flex gap-2">
                                <input
                                    value={input} onChange={e => setInput(e.target.value)}
                                    placeholder="Pregúntale a CoCo..."
                                    className="flex-1 px-3.5 py-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-sm font-medium outline-none focus:ring-2 focus:ring-pink-400/30"
                                />
                                <button type="submit" disabled={!input.trim() || loading}
                                    className="p-2.5 bg-gradient-to-r from-pink-500 to-purple-500 rounded-xl text-white disabled:opacity-40 hover:scale-105 transition-transform shadow-md">
                                    {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                                </button>
                            </form>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* FAB — girl emoji, pink gradient */}
            <motion.button
                onClick={() => setOpen(o => !o)}
                whileHover={{ scale: 1.08 }}
                whileTap={{ scale: 0.94 }}
                className="relative flex items-center justify-center rounded-2xl text-2xl"
                style={{
                    width: 56, height: 56,
                    background: "linear-gradient(135deg, #ec4899, #f43f5e, #a855f7)",
                    boxShadow: "0 8px 32px rgba(236,72,153,0.5)"
                }}
            >
                <AnimatePresence mode="wait">
                    {open
                        ? <motion.span key="x" initial={{ rotate: -90, opacity: 0 }} animate={{ rotate: 0, opacity: 1 }} exit={{ rotate: 90, opacity: 0 }}><X className="h-6 w-6 text-white" /></motion.span>
                        : <motion.span key="g" initial={{ rotate: 90, opacity: 0 }} animate={{ rotate: 0, opacity: 1 }} exit={{ rotate: -90, opacity: 0 }} className="text-2xl">👩‍💻</motion.span>
                    }
                </AnimatePresence>

                {/* Pulse */}
                {!open && <span className="absolute inset-0 rounded-2xl animate-ping opacity-30" style={{ background: "linear-gradient(135deg,#ec4899,#a855f7)" }} />}

                {/* Label tooltip */}
                {!open && (
                    <span className="absolute right-full mr-3 px-3 py-1.5 bg-white dark:bg-slate-800 rounded-xl shadow-lg text-xs font-black text-pink-600 whitespace-nowrap border border-pink-100 pointer-events-none">
                        👋 ¡Hola! Soy CoCo
                    </span>
                )}
            </motion.button>
        </div>
    );
}

"use client";

import { useState, useRef, useEffect } from 'react';
import { useNotifications, Notification } from '@/lib/notificationContext';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Bell, Check, X, Info, CheckCircle, AlertTriangle, AlertCircle,
    ExternalLink, Trash2, CheckCheck
} from 'lucide-react';
import Link from 'next/link';

const iconMap = {
    info: Info,
    success: CheckCircle,
    warning: AlertTriangle,
    alert: AlertCircle,
};

const colorMap = {
    info: 'bg-blue-100 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400',
    success: 'bg-emerald-100 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400',
    warning: 'bg-amber-100 dark:bg-amber-500/20 text-amber-600 dark:text-amber-400',
    alert: 'bg-red-100 dark:bg-red-500/20 text-red-600 dark:text-red-400',
};

function formatTimeAgo(date: Date): string {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffMins < 1) return 'Ahora';
    if (diffMins < 60) return `Hace ${diffMins}m`;
    if (diffHours < 24) return `Hace ${diffHours}h`;
    return `Hace ${diffDays}d`;
}

function NotificationItem({ notification, onRead, onRemove }: {
    notification: Notification;
    onRead: () => void;
    onRemove: () => void;
}) {
    const Icon = iconMap[notification.type];

    const content = (
        <div className={`relative p-4 rounded-xl border transition-all ${notification.read
                ? 'bg-slate-50 dark:bg-slate-800/50 border-slate-100 dark:border-slate-700/50'
                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm'
            }`}>
            {!notification.read && (
                <div className="absolute top-4 right-4 w-2 h-2 bg-indigo-500 rounded-full" />
            )}
            <div className="flex gap-3">
                <div className={`p-2 rounded-lg flex-shrink-0 ${colorMap[notification.type]}`}>
                    <Icon className="h-4 w-4" />
                </div>
                <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-2">
                        <p className={`text-sm font-semibold ${notification.read ? 'text-slate-600 dark:text-slate-400' : 'text-slate-900 dark:text-white'}`}>
                            {notification.title}
                        </p>
                    </div>
                    <p className="text-sm text-slate-500 dark:text-slate-400 mt-0.5 line-clamp-2">
                        {notification.message}
                    </p>
                    <div className="flex items-center gap-3 mt-2">
                        <span className="text-xs text-slate-400 dark:text-slate-500">
                            {formatTimeAgo(notification.timestamp)}
                        </span>
                        {!notification.read && (
                            <button
                                onClick={(e) => { e.preventDefault(); e.stopPropagation(); onRead(); }}
                                className="text-xs font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-300"
                            >
                                Marcar leído
                            </button>
                        )}
                    </div>
                </div>
                <button
                    onClick={(e) => { e.preventDefault(); e.stopPropagation(); onRemove(); }}
                    className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 transition-colors"
                >
                    <X className="h-4 w-4" />
                </button>
            </div>
        </div>
    );

    if (notification.link) {
        return (
            <Link href={notification.link} onClick={onRead}>
                {content}
            </Link>
        );
    }

    return content;
}

export function NotificationCenter() {
    const { notifications, unreadCount, markAsRead, markAllAsRead, removeNotification, clearAll } = useNotifications();
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    // Close on click outside
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        }
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Close on escape
    useEffect(() => {
        function handleEscape(e: KeyboardEvent) {
            if (e.key === 'Escape') setIsOpen(false);
        }
        window.addEventListener('keydown', handleEscape);
        return () => window.removeEventListener('keydown', handleEscape);
    }, []);

    return (
        <div className="relative" ref={dropdownRef}>
            {/* Trigger Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="relative p-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
            >
                <Bell className="h-5 w-5 text-slate-600 dark:text-slate-400" />
                {unreadCount > 0 && (
                    <motion.span
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        className="absolute -top-1 -right-1 min-w-[20px] h-5 px-1.5 bg-red-500 text-white text-xs font-bold rounded-full flex items-center justify-center"
                    >
                        {unreadCount > 9 ? '9+' : unreadCount}
                    </motion.span>
                )}
            </button>

            {/* Dropdown */}
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute right-0 mt-2 w-96 max-h-[70vh] bg-white dark:bg-slate-900 rounded-2xl shadow-2xl shadow-slate-200/50 dark:shadow-slate-950/50 border border-slate-200 dark:border-slate-700 overflow-hidden z-50"
                    >
                        {/* Header */}
                        <div className="p-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                            <div>
                                <h3 className="font-bold text-slate-900 dark:text-white">Notificaciones</h3>
                                <p className="text-xs text-slate-500 dark:text-slate-400">
                                    {unreadCount > 0 ? `${unreadCount} sin leer` : 'Todo al día'}
                                </p>
                            </div>
                            <div className="flex items-center gap-2">
                                {unreadCount > 0 && (
                                    <button
                                        onClick={markAllAsRead}
                                        className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 hover:text-slate-700 dark:hover:text-slate-300 transition-colors"
                                        title="Marcar todo como leído"
                                    >
                                        <CheckCheck className="h-4 w-4" />
                                    </button>
                                )}
                                {notifications.length > 0 && (
                                    <button
                                        onClick={clearAll}
                                        className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-500 hover:text-slate-700 dark:hover:text-slate-300 transition-colors"
                                        title="Limpiar todo"
                                    >
                                        <Trash2 className="h-4 w-4" />
                                    </button>
                                )}
                            </div>
                        </div>

                        {/* Notifications List */}
                        <div className="overflow-y-auto max-h-[50vh] p-3 space-y-2">
                            {notifications.length === 0 ? (
                                <div className="text-center py-8">
                                    <div className="w-12 h-12 mx-auto mb-3 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center">
                                        <Bell className="h-6 w-6 text-slate-400" />
                                    </div>
                                    <p className="text-sm text-slate-500 dark:text-slate-400">No hay notificaciones</p>
                                </div>
                            ) : (
                                notifications.map((notification) => (
                                    <NotificationItem
                                        key={notification.id}
                                        notification={notification}
                                        onRead={() => markAsRead(notification.id)}
                                        onRemove={() => removeNotification(notification.id)}
                                    />
                                ))
                            )}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

// Compact version for sidebar
export function NotificationBell() {
    const { unreadCount } = useNotifications();

    return (
        <div className="relative">
            <Bell className="h-5 w-5 text-slate-600 dark:text-slate-400" />
            {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
                    {unreadCount > 9 ? '9' : unreadCount}
                </span>
            )}
        </div>
    );
}

