                                            {booking.users?.name || 'Residente'}
                                        </div>
                                        <div className="flex items-center gap-1.5">
                                            <CalendarIcon className="h-4 w-4" />
                                            {new Date(booking.date).toLocaleDateString()}
                                        </div>
                                        <div className="flex items-center gap-1.5">
                                            <Clock className="h-4 w-4" />
                                            {booking.start_time.substring(0, 5)} - {booking.end_time.substring(0, 5)}
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {booking.status === 'pending' ? (
                                <div className="flex gap-3">
                                    <button
                                        onClick={() => handleUpdateStatus(booking.id, 'confirmed')}
                                        className="h-12 px-6 bg-emerald-50 hover:bg-emerald-500 hover:text-white text-emerald-600 dark:bg-emerald-500/10 dark:hover:bg-emerald-500 rounded-2xl font-black text-sm flex items-center gap-2 transition-all active:scale-95"
                                    >
                                        <Check className="h-5 w-5" /> Aprobar
                                    </button>
                                    <button
                                        onClick={() => handleUpdateStatus(booking.id, 'cancelled')}
                                        className="h-12 w-12 bg-rose-50 hover:bg-rose-500 hover:text-white text-rose-600 dark:bg-rose-500/10 dark:hover:bg-rose-500 rounded-2xl flex items-center justify-center transition-all active:scale-95"
                                        title="Rechazar"
                                    >
                                        <X className="h-5 w-5" />
                                    </button>
                                </div>
                            ) : (
                                <div className="text-right">
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                        Solicitado el {new Date(booking.created_at).toLocaleDateString()}
                                    </p>
                                </div>
                            )}

                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
    Activity, Shield, Settings, AlertTriangle,
    CheckCircle2, Clock, MapPin, Wrench,
    ChevronRight, MoreHorizontal, FlaskConical,
    Zap, Droplets, ArrowUpRight, FileText,
    History, DollarSign, User
} from "lucide-react";
import { BuildingAsset, MaintenanceLog } from "@/lib/types";
import { supabase } from "@/lib/supabase";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/Dialog";

export function AssetInventory() {
    const [assets, setAssets] = useState<BuildingAsset[]>([]);
    const [selectedAsset, setSelectedAsset] = useState<BuildingAsset | null>(null);
    const [assetLogs, setAssetLogs] = useState<MaintenanceLog[]>([]);
    const [isLogOpen, setIsLogOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchAssets = async () => {
            try {
                const { data, error } = await supabase.from('building_assets').select('*');
                if (data && !error) {
                    const mappedAssets = data.map((dbAsset: any) => ({
                        id: dbAsset.id,
                        name: dbAsset.name,
                        category: dbAsset.category,
                        brand: dbAsset.brand,
                        model: dbAsset.model,
                        installationDate: dbAsset.installation_date || dbAsset.installationDate,
                        location: dbAsset.location,
                        healthStatus: dbAsset.health_status || dbAsset.healthStatus,
                        lastMaintenance: dbAsset.last_maintenance || dbAsset.lastMaintenance,
                        nextMaintenance: dbAsset.next_maintenance || dbAsset.nextMaintenance,
                    }));
                    setAssets(mappedAssets as BuildingAsset[]);
                }
            } catch (err) {
                console.error("Error fetching assets:", err);
            } finally {
                setIsLoading(false);
            }
        };
        fetchAssets();
    }, []);

    const handleOpenLog = async (asset: BuildingAsset) => {
        setSelectedAsset(asset);
        setIsLogOpen(true);
        try {
            const { data, error } = await supabase.from('maintenance_logs').select('*').eq('asset_id', asset.id);
            if (data && !error) {
                const mappedLogs = data.map((log: any) => ({
                    id: log.id,
                    assetId: log.asset_id || log.assetId,
                    performedBy: log.performed_by || log.performedBy,
                    description: log.description,
                    cost: log.cost,
                    date: log.date
                }));
                setAssetLogs(mappedLogs as MaintenanceLog[]);
            } else {
                setAssetLogs([]);
            }
        } catch (err) {
            console.error(err);
        }
    };

    const getStatusColor = (status: BuildingAsset['healthStatus']) => {
        switch (status) {
            case 'optimal': return 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.4)]';
            case 'warning': return 'bg-amber-500 shadow-[0_0_15px_rgba(245,158,11,0.4)]';
            case 'critical': return 'bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.4)]';
            default: return 'bg-slate-500';
        }
    };

    const getCategoryIcon = (category: BuildingAsset['category']) => {
        switch (category) {
            case 'elevator': return <ArrowUpRight className="h-6 w-6" />;
            case 'pump': return <Droplets className="h-6 w-6" />;
            case 'generator': return <Zap className="h-6 w-6" />;
            default: return <Settings className="h-6 w-6" />;
        }
    };

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {isLoading && <div className="col-span-full p-4 text-center">Cargando activos...</div>}
            {!isLoading && assets.length === 0 && <div className="col-span-full p-4 text-center text-slate-500">No hay activos registrados.</div>}
            {assets.map((asset, i) => (
                <motion.div
                    key={asset.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.1 }}
                    whileHover={{ y: -5 }}
                    className="bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-xl shadow-slate-200/20 dark:shadow-none overflow-hidden group"
                >
                    <div className="p-8 space-y-8">
                        {/* Header */}
                        <div className="flex justify-between items-start">
                            <div className={`p-4 rounded-2xl ${asset.healthStatus === 'optimal' ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-400' :
                                asset.healthStatus === 'warning' ? 'bg-amber-50 text-amber-600 dark:bg-amber-500/10 dark:text-amber-400' :
                                    'bg-red-50 text-red-600 dark:bg-red-500/10 dark:text-red-400'
                                }`}>
                                {getCategoryIcon(asset.category)}
                            </div>
                            <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 dark:bg-slate-800 rounded-full border border-slate-100 dark:border-slate-700">
                                <div className={`h-2.5 w-2.5 rounded-full ${getStatusColor(asset.healthStatus)}`} />
                                <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
                                    {asset.healthStatus === 'optimal' ? 'Operativo' :
                                        asset.healthStatus === 'warning' ? 'Atención' : 'Crítico'}
                                </span>
                            </div>
                        </div>

                        {/* Title & Stats */}
                        <div className="space-y-2">
                            <h3 className="text-xl font-black text-slate-900 dark:text-white leading-tight group-hover:text-blue-600 transition-colors">
                                {asset.name}
                            </h3>
                            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <MapPin className="h-3 w-3" />
                                {asset.location}
                            </p>
                        </div>

                        {/* Specs Table */}
                        <div className="grid grid-cols-2 gap-4 py-6 border-y border-slate-50 dark:border-slate-800">
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Marca / Modelo</p>
                                <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{asset.brand} {asset.model}</p>
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Instalación</p>
                                <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{new Date(asset.installationDate).getFullYear()}</p>
                            </div>
                        </div>

                        {/* Maintenance Info */}
                        <div className="space-y-4">
                            <div className="flex items-center justify-between text-xs font-bold">
                                <span className="text-slate-400 uppercase tracking-widest">Próxima Revisión</span>
                                <span className={`flex items-center gap-2 ${asset.healthStatus === 'critical' ? 'text-red-600' : 'text-slate-900 dark:text-white'
                                    }`}>
                                    <Clock className="h-3 w-3" />
                                    {new Date(asset.nextMaintenance).toLocaleDateString()}
                                </span>
                            </div>
                            <div className="h-1.5 w-full bg-slate-50 dark:bg-slate-800 rounded-full overflow-hidden">
                                <motion.div
                                    initial={{ width: 0 }}
                                    animate={{ width: asset.healthStatus === 'optimal' ? '85%' : asset.healthStatus === 'warning' ? '45%' : '15%' }}
                                    className={`h-full rounded-full ${asset.healthStatus === 'optimal' ? 'bg-emerald-500' :
                                        asset.healthStatus === 'warning' ? 'bg-amber-500' : 'bg-red-500'
                                        }`}
                                />
                            </div>
                        </div>
                    </div>

                    {/* Footer Action */}
                    <button
                        onClick={() => handleOpenLog(asset)}
                        className="w-full py-6 bg-slate-50 dark:bg-slate-800/50 text-xs font-black uppercase tracking-widest text-slate-500 hover:text-blue-600 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all flex items-center justify-center gap-2 border-t border-slate-50 dark:border-slate-800"
                    >
                        Ver Bitácora Técnica
                        <ChevronRight className="h-4 w-4" />
                    </button>
                </motion.div>
            ))}

            {/* Technical Log Dialog */}
            <Dialog open={isLogOpen} onOpenChange={setIsLogOpen}>
                <DialogContent className="sm:max-w-[600px] bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl border-white/20 dark:border-slate-800 rounded-[2.5rem] p-0 shadow-2xl overflow-hidden">
                    <div className="bg-slate-900 p-10 text-white relative">
                        <div className="absolute top-0 right-0 p-8 opacity-10">
                            <History className="h-24 w-24 text-blue-400" />
                        </div>
                        <DialogHeader className="relative z-10">
                            <div className="flex items-center gap-3 mb-4">
                                <div className="p-2 bg-blue-500/20 rounded-lg">
                                    <FileText className="h-5 w-5 text-blue-400" />
                                </div>
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400">Bitácora Técnica</span>
                            </div>
                            <DialogTitle className="text-3xl font-black">{selectedAsset?.name}</DialogTitle>
                            <DialogDescription className="text-slate-400 font-medium">
                                Historial completo de intervenciones y mantenimiento preventivo.
                            </DialogDescription>
                        </DialogHeader>
                    </div>

                    <div className="p-10 space-y-8 max-h-[500px] overflow-y-auto custom-scrollbar">
                        {assetLogs.length > 0 ? (
                            <div className="space-y-8">
                                {assetLogs.map((log, i) => (
                                    <div key={log.id} className="relative pl-8">
                                        {i !== assetLogs.length - 1 && (
                                            <div className="absolute left-0 top-6 bottom-[-32px] w-[2px] bg-slate-100 dark:bg-slate-800" />
                                        )}
                                        <div className="absolute left-[-4px] top-1.5 h-2.5 w-2.5 rounded-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]" />

                                        <div className="space-y-4">
                                            <div className="flex items-center justify-between">
                                                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                                    {new Date(log.date).toLocaleDateString('es-CL', { day: '2-digit', month: 'long', year: 'numeric' })}
                                                </span>
                                                <span className="px-3 py-1 bg-emerald-50 dark:bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 rounded-lg text-[10px] font-black tracking-wider uppercase">
                                                    Realizado
                                                </span>
                                            </div>

                                            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-2xl space-y-3">
                                                <p className="text-sm font-bold text-slate-900 dark:text-white leading-relaxed">
                                                    {log.description}
                                                </p>
                                                <div className="flex flex-wrap gap-4 pt-2">
                                                    <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                                        <User className="h-3 w-3" />
                                                        {log.performedBy}
                                                    </div>
                                                    <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest">
                                                        <DollarSign className="h-3 w-3" />
                                                        ${(log.cost || 0).toLocaleString('es-CL')}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="text-center py-10 space-y-4">
                                <div className="mx-auto w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-300">
                                    <Activity className="h-8 w-8" />
                                </div>
                                <p className="text-slate-500 font-bold italic">No hay registros previos para este activo.</p>
                            </div>
                        )}
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
    Calendar, AlertCircle, Clock, CheckCircle2,
    CalendarDays, Wrench, BarChart3, TrendingUp,
    AlertTriangle, History, ArrowRight, Activity,
    Check, X, Trash2, Info
} from "lucide-react";
import { MaintenanceTask, BuildingAsset, MaintenanceLog } from "@/lib/types";
import { supabase } from "@/lib/supabase";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter
} from "@/components/ui/Dialog";
import { Button } from "@/components/ui/Button";
import { useToast } from "@/components/ui/Toast";

export function MaintenanceDashboard() {
    const [tasks, setTasks] = useState<MaintenanceTask[]>([]);
    const [assets, setAssets] = useState<BuildingAsset[]>([]);
    const [logs, setLogs] = useState<MaintenanceLog[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedTask, setSelectedTask] = useState<MaintenanceTask | null>(null);
    const [isDetailOpen, setIsDetailOpen] = useState(false);
    const { toast } = useToast();

    useEffect(() => {
        const fetchData = async () => {
            setIsLoading(true);
            try {
                const [tasksRes, assetsRes, logsRes] = await Promise.all([
                    supabase.from('maintenance_tasks').select('*'),
                    supabase.from('building_assets').select('*'),
                    supabase.from('maintenance_logs').select('*').order('date', { ascending: false }).limit(5)
                ]);

                if (tasksRes.data) {
                    setTasks(tasksRes.data.map((t: any) => ({
                        id: t.id,
                        assetId: t.asset_id || t.assetId,
                        title: t.title,
                        description: t.description,
                        frequency: t.frequency,
                        dueDate: t.due_date || t.dueDate,
                        priority: t.priority,
                        status: t.status
                    })));
                }

                if (assetsRes.data) {
                    setAssets(assetsRes.data.map((dbAsset: any) => ({
                        id: dbAsset.id,
                        name: dbAsset.name,
                        category: dbAsset.category,
                        brand: dbAsset.brand,
                        model: dbAsset.model,
                        installationDate: dbAsset.installation_date || dbAsset.installationDate,
                        location: dbAsset.location,
                        healthStatus: dbAsset.health_status || dbAsset.healthStatus,
                        lastMaintenance: dbAsset.last_maintenance || dbAsset.lastMaintenance,
                        nextMaintenance: dbAsset.next_maintenance || dbAsset.nextMaintenance,
                    })));
                }

                if (logsRes.data) {
                    setLogs(logsRes.data.map((l: any) => ({
                        id: l.id,
                        assetId: l.asset_id || l.assetId,
                        performedBy: l.performed_by || l.performedBy,
                        description: l.description,
                        cost: l.cost,
                        date: l.date
                    })));
                }
            } catch (err) {
                console.error("Error fetching maintenance data:", err);
            } finally {
                setIsLoading(false);
            }
        };

        fetchData();
    }, []);

    const handleCompleteTask = async (taskId: string) => {
        try {
            await supabase.from('maintenance_tasks').update({ status: 'completed' }).eq('id', taskId);
            setTasks(prev => prev.map(t =>
                t.id === taskId ? { ...t, status: 'completed' } : t
            ));
            setIsDetailOpen(false);
            toast({
                title: "Tarea Completada",
                description: "El registro ha sido actualizado exitosamente.",
                variant: "success"
            });
        } catch (error) {
            console.error(error);
        }
    };

    if (isLoading) return <div className="p-8 text-center">Cargando dashboard de mantenimiento...</div>;

    const overdueCount = tasks.filter((t: any) => t.status === 'overdue').length;
    const pendingCount = tasks.filter((t: any) => t.status === 'pending').length;
    const criticalAssets = assets.filter((a: any) => a.healthStatus === 'critical').length;

    return (
        <div className="space-y-12">
            {/* Quick Stats */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                <div className="bg-white/60 dark:bg-slate-800/40 backdrop-blur-xl p-8 rounded-[2.5rem] border border-white/50 dark:border-slate-700/50 shadow-xl shadow-slate-200/20 dark:shadow-black/40">
                    <div className="flex items-center gap-4 mb-6">
                        <div className="p-3 bg-red-50 dark:bg-red-500/10 rounded-2xl">
                            <AlertCircle className="h-6 w-6 text-red-600 dark:text-red-400" />
                        </div>
                        <h3 className="font-black text-slate-900 dark:text-white uppercase text-[10px] tracking-widest">Tareas Vencidas</h3>
                    </div>
                    <p className="text-4xl font-black text-slate-900 dark:text-white">{overdueCount}</p>
                    <p className="text-xs font-bold text-red-500 mt-2 flex items-center gap-1">
                        <AlertTriangle className="h-3 w-3" />
                        Requiere acción inmediata
                    </p>
                </div>

                <div className="bg-white/60 dark:bg-slate-800/40 backdrop-blur-xl p-8 rounded-[2.5rem] border border-white/50 dark:border-slate-700/50 shadow-xl shadow-slate-200/20 dark:shadow-black/40">
                    <div className="flex items-center gap-4 mb-6">
                        <div className="p-3 bg-blue-50 dark:bg-blue-500/10 rounded-2xl">
                            <Clock className="h-6 w-6 text-blue-600 dark:text-blue-400" />
                        </div>
                        <h3 className="font-black text-slate-900 dark:text-white uppercase text-[10px] tracking-widest">Pendientes</h3>
                    </div>
                    <p className="text-4xl font-black text-slate-900 dark:text-white">{pendingCount}</p>
                    <p className="text-xs font-bold text-slate-400 mt-2">Próximos 7 días</p>
                </div>

                <div className="bg-white/60 dark:bg-slate-800/40 backdrop-blur-xl p-8 rounded-[2.5rem] border border-white/50 dark:border-slate-700/50 shadow-xl shadow-slate-200/20 dark:shadow-black/40">
                    <div className="flex items-center gap-4 mb-6">
                        <div className="p-3 bg-amber-50 dark:bg-amber-500/10 rounded-2xl">
                            <Activity className="h-6 w-6 text-amber-600 dark:text-amber-400" />
                        </div>
                        <h3 className="font-black text-slate-900 dark:text-white uppercase text-[10px] tracking-widest">Activos Críticos</h3>
                    </div>
                    <p className="text-4xl font-black text-slate-900 dark:text-white">{criticalAssets}</p>
                    <p className="text-xs font-bold text-amber-500 mt-2">Revisar hoja de vida</p>
                </div>

                <div className="bg-slate-900/80 dark:bg-slate-950/80 backdrop-blur-xl border border-slate-800 p-8 rounded-[2.5rem] shadow-2xl shadow-blue-500/10 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:rotate-12 transition-transform duration-500">
                        <TrendingUp className="h-20 w-20 text-blue-500" />
                    </div>
                    <div className="relative z-10 flex flex-col justify-between h-full">
                        <div>
                            <h3 className="font-black text-white uppercase text-[10px] tracking-widest mb-1">Costo Operativo</h3>
                            <p className="text-2xl font-black text-white">$450.000</p>
                        </div>
