                            <div className="grid grid-cols-2 gap-6 p-6 bg-slate-50 dark:bg-slate-800/50 rounded-[2rem]">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Frecuencia</p>
                                    <p className="font-bold text-slate-900 dark:text-white capitalize">{selectedTask.frequency === 'weekly' ? 'Semanal' : selectedTask.frequency === 'monthly' ? 'Mensual' : selectedTask.frequency === 'quarterly' ? 'Trimestral' : 'Anual'}</p>
                                </div>
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Vencimiento</p>
                                    <p className="font-bold text-slate-900 dark:text-white">{new Date(selectedTask.dueDate).toLocaleDateString()}</p>
                                </div>
                            </div>

                            <div className="p-4 bg-blue-50 dark:bg-blue-500/10 rounded-2xl flex gap-3 border border-blue-100 dark:border-blue-500/20">
                                <Info className="h-5 w-5 text-blue-600 shrink-0" />
                                <p className="text-[11px] font-medium text-blue-700 leading-relaxed">
                                    Al completar esta tarea, se generará automáticamente un registro en la bitácora técnica del activo correspondiente.
                                </p>
                            </div>

                            <div className="flex gap-4">
                                <Button
                                    onClick={() => setIsDetailOpen(false)}
                                    variant="outline"
                                    className="flex-1 h-16 rounded-2xl font-black"
                                >
                                    Cerrar
                                </Button>
                                {selectedTask.status !== 'completed' && (
                                    <Button
                                        onClick={() => handleCompleteTask(selectedTask.id)}
                                        className="flex-[2] h-16 rounded-2xl bg-blue-600 hover:bg-blue-700 text-white font-black shadow-xl shadow-blue-500/20 transition-all"
                                    >
                                        <Check className="mr-2 h-5 w-5" />
                                        Marcar como Completada
                                    </Button>
                                )}
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
    Plus, BarChart3, Clock, Settings,
    MoreHorizontal, Filter, Search,
    MessageSquare, AlertCircle, CheckCircle2,
    Calendar, Vote
} from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Input";
import { Poll } from "@/lib/types";
import { PollService } from "@/lib/services/supabaseServices";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/Dialog";
import { useToast } from "@/components/ui/Toast";
import { useAuth } from "@/lib/authContext";

export function PollManager() {
    const { user } = useAuth();
    const [polls, setPolls] = useState<Poll[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [newPoll, setNewPoll] = useState({ title: "", description: "", category: "community" });
    const { toast } = useToast();

    useEffect(() => {
        const loadPolls = async () => {
            setIsLoading(true);
            try {
                const data = await PollService.getAll();
                setPolls(data as Poll[]);
            } catch (err) {
                console.error("Error loading polls:", err);
            } finally {
                setIsLoading(false);
            }
        };
        loadPolls();
    }, []);

    const handleCreatePoll = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user) return;

        try {
            const pollData = {
                title: newPoll.title,
                description: newPoll.description,
                category: newPoll.category,
                end_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
                created_by: user.id
            };
            const createdPoll = await PollService.create(pollData, ['A favor', 'En contra']);

            if (createdPoll) {
                setPolls([createdPoll as any, ...polls]);
                setIsDialogOpen(false);
                setNewPoll({ title: "", description: "", category: "community" });
                toast({
                    title: "Votación Publicada",
                    description: "La consulta ya está disponible para todos los residentes.",
                    variant: "success"
                });
            }
        } catch (error) {
            console.error("Error creating poll:", error);
