                        </div>
                        <div className="flex items-center gap-3">
                            <div className="h-3 w-3 rounded-full bg-emerald-500 animate-pulse" />
                            <span className="text-sm font-bold text-slate-300">Decisiones Legales</span>
                        </div>
                    </div>
