                                    >
                                        <option value="community">Comunidad & Eventos</option>
                                        <option value="maintenance">Mantención & Obras</option>
                                        <option value="rules">Reglamento & Normas</option>
                                    </select>
                                </div>
                                <div className="space-y-2">
