                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Leído</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="h-3 w-3 rounded-md bg-amber-100 dark:bg-amber-500/20 border border-amber-200 dark:border-amber-500/30" />
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Alerta de Consumo</span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="h-3 w-3 rounded-md bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700" />
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Pendiente</span>
                </div>
            </div>
        </div>
    );
}

"use client";

import {
    AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
    BarChart, Bar, PieChart, Pie, Cell, LineChart, Line
} from 'recharts';

// Custom tooltip styles
const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
        return (
            <div className="bg-white dark:bg-slate-800 p-3 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700">
                <p className="text-sm font-semibold text-slate-900 dark:text-white">{label}</p>
                {payload.map((entry: any, index: number) => (
                    <p key={index} className="text-sm text-slate-600 dark:text-slate-400">
                        {entry.name}: <span className="font-medium text-slate-900 dark:text-white">${entry.value.toLocaleString('es-CL')} CLP</span>
                    </p>
                ))}
            </div>
        );
    }
    return null;
};

// Expense Area Chart
interface ExpenseData {
    month: string;
    monto: number;
}

export function ExpenseAreaChart({ data }: { data: ExpenseData[] }) {
    return (
        <ResponsiveContainer width="100%" height={250}>
            <AreaChart data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                    <linearGradient id="colorExpense" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3} />
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0} />
                    </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" className="dark:stroke-slate-700" />
                <XAxis
                    dataKey="month"
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 12, fill: '#94a3b8' }}
                />
                <YAxis
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 12, fill: '#94a3b8' }}
                    tickFormatter={(value) => `$${(value / 1000).toFixed(0)}k CLP`}
                />
                <Tooltip content={<CustomTooltip />} />
                <Area
                    type="monotone"
                    dataKey="monto"
                    stroke="#6366f1"
                    strokeWidth={2}
                    fill="url(#colorExpense)"
                    name="Gasto"
                />
            </AreaChart>
        </ResponsiveContainer>
    );
}

// Expense Category Pie Chart
interface CategoryData {
    name: string;
    value: number;
    color: string;
}

const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4'];

export function ExpensePieChart({ data }: { data: CategoryData[] }) {
    return (
        <ResponsiveContainer width="100%" height={200}>
            <PieChart>
                <Pie
                    data={data}
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={80}
                    paddingAngle={2}
                    dataKey="value"
                >
                    {data.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color || COLORS[index % COLORS.length]} />
                    ))}
                </Pie>
                <Tooltip
                    formatter={(value) => [`$${(value as number).toLocaleString('es-CL')} CLP`, 'Monto']}
                    contentStyle={{
                        backgroundColor: 'white',
                        border: '1px solid #e2e8f0',
                        borderRadius: '12px',
                        boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
                    }}
                />
            </PieChart>
        </ResponsiveContainer>
    );
}

// Bar Chart for Amenity Usage
interface UsageData {
    name: string;
    reservas: number;
}

export function AmenityUsageChart({ data }: { data: UsageData[] }) {
    return (
        <ResponsiveContainer width="100%" height={200}>
            <BarChart data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" className="dark:stroke-slate-700" />
                <XAxis
                    dataKey="name"
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 11, fill: '#94a3b8' }}
                />
                <YAxis
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 12, fill: '#94a3b8' }}
                    label={{ value: 'N° Reservas', angle: -90, position: 'insideLeft', style: { fill: '#94a3b8', fontSize: 12 } }}
                />
                <Tooltip
                    formatter={(value) => [value as number, 'Reservas']}
                    contentStyle={{
                        backgroundColor: 'white',
                        border: '1px solid #e2e8f0',
                        borderRadius: '12px',
                        boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)',
                    }}
                />
                <Bar
                    dataKey="reservas"
                    fill="#10b981"
                    radius={[4, 4, 0, 0]}
                />
            </BarChart>
        </ResponsiveContainer>
    );
}

// Stat Card with mini sparkline
interface SparklineProps {
    data: number[];
    color: string;
}

export function Sparkline({ data, color }: SparklineProps) {
    const chartData = data.map((value, index) => ({ value, index }));

    return (
        <ResponsiveContainer width="100%" height={40}>
            <LineChart data={chartData}>
                <Line
                    type="monotone"
                    dataKey="value"
                    stroke={color}
                    strokeWidth={2}
                    dot={false}
                />
            </LineChart>
        </ResponsiveContainer>
    );
}

"use client";

import { useState, useEffect } from "react";
import { MarketplaceItem, User } from "@/lib/types";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle
} from "@/components/ui/Dialog";
import { Send, User as UserIcon, ShieldCheck } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

interface ChatModalProps {
    item: MarketplaceItem | null;
    isOpen: boolean;
    onClose: () => void;
    currentUser: User | null;
}

export function ChatModal({ item, isOpen, onClose, currentUser }: ChatModalProps) {
    const [messages, setMessages] = useState<{ sender: string, text: string, time: string }[]>([]);
    const [inputText, setInputText] = useState("");

    useEffect(() => {
        if (isOpen && item) {
            // Initial mock message from system or seller
            setMessages([
                {
                    sender: "system",
                    text: `Has iniciado una conversación por: ${item.title}`,
                    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                }
            ]);
        }
    }, [isOpen, item]);

    const handleSendMessage = (e: React.FormEvent) => {
        e.preventDefault();
        if (!inputText.trim()) return;

        const newMessage = {
            sender: "me",
            text: inputText,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setMessages([...messages, newMessage]);
        setInputText("");

        // Simulated response from seller
        setTimeout(() => {
            setMessages(prev => [...prev, {
                sender: "seller",
                text: "¡Hola! Sí, aún lo tengo disponible. ¿Te gustaría venir a verlo hoy?",
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            }]);
        }, 1500);
    };

    if (!item) return null;

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-md p-0 overflow-hidden rounded-[2rem] border-none shadow-2xl">
                <div className="flex flex-col h-[600px] bg-slate-50 dark:bg-slate-950">
                    {/* Header */}
                    <div className="p-6 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 flex items-center gap-4">
                        <div className="h-12 w-12 rounded-2xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-white font-bold text-lg">
                            V
                        </div>
                        <div className="flex-1">
                            <DialogTitle className="font-bold text-slate-900 dark:text-white">Valentina Rivas</DialogTitle>
                            <p className="text-xs text-emerald-500 font-bold uppercase tracking-widest">Vendedor Online</p>
                        </div>
                        <div className="p-2 bg-blue-50 dark:bg-blue-500/10 rounded-xl">
                            <ShieldCheck className="h-5 w-5 text-blue-600 dark:text-blue-400" />
                        </div>
                    </div>

                    {/* Messages Area */}
                    <div className="flex-1 overflow-y-auto p-6 space-y-4">
                        <AnimatePresence>
                            {messages.map((msg, idx) => (
                                <motion.div
                                    key={idx}
                                    initial={{ opacity: 0, y: 10, scale: 0.95 }}
                                    animate={{ opacity: 1, y: 0, scale: 1 }}
                                    className={`flex ${msg.sender === 'me' ? 'justify-end' : 'justify-start'}`}
                                >
                                    <div className={`max-w-[80%] p-4 rounded-2xl text-sm font-medium shadow-sm ${msg.sender === 'me'
                                        ? 'bg-blue-600 text-white rounded-tr-none'
                                        : msg.sender === 'system'
                                            ? 'bg-slate-200 dark:bg-slate-800 text-slate-500 text-center text-xs w-full'
                                            : 'bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-200 rounded-tl-none'
                                        }`}>
                                        {msg.text}
                                        {msg.sender !== 'system' && (
                                            <p className={`text-[10px] mt-1 ${msg.sender === 'me' ? 'text-blue-200' : 'text-slate-400'}`}>
                                                {msg.time}
                                            </p>
                                        )}
                                    </div>
                                </motion.div>
                            ))}
                        </AnimatePresence>
                    </div>

                    {/* Input Area */}
                    <form onSubmit={handleSendMessage} className="p-6 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
                        <div className="flex gap-2">
                            <input
                                type="text"
                                placeholder="Escribe un mensaje..."
                                className="flex-1 h-12 px-4 rounded-xl bg-slate-100 dark:bg-slate-800 border-none text-sm font-medium focus:ring-2 focus:ring-blue-500/20"
                                value={inputText}
                                onChange={(e) => setInputText(e.target.value)}
                            />
                            <button
                                type="submit"
                                className="h-12 w-12 flex items-center justify-center bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all active:scale-90"
                            >
                                <Send className="h-5 w-5" />
                            </button>
                        </div>
                    </form>
                </div>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { Search, X, Grid3X3, Smartphone, Armchair, Shirt, Package } from "lucide-react";
import { motion } from "framer-motion";

interface ProductFiltersProps {
