"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
    CheckCircle2, Clock, Users, ChevronRight,
    BarChart3, Calendar, Info, Vote as VoteIcon
} from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Poll, PollOption } from "@/lib/types";
import { useToast } from "@/components/ui/Toast";

interface PollCardProps {
    poll: Poll;
    onVote?: (optionId: string) => void;
    isAdmin?: boolean;
    initialHasVoted?: boolean;
    initialSelectedOption?: string | null;
}

export function PollCard({ poll, onVote, isAdmin, initialHasVoted = false, initialSelectedOption = null }: PollCardProps) {
    const [selectedOption, setSelectedOption] = useState<string | null>(initialSelectedOption);
    const [hasVoted, setHasVoted] = useState(initialHasVoted);
    const { toast } = useToast();

    const handleVote = () => {
        if (!selectedOption) return;
        setHasVoted(true);
        onVote?.(selectedOption);
        toast({
            title: "¡Voto Registrado!",
            description: "Gracias por participar en la comunidad.",
            variant: "success"
        });
    };

    // Prevent double counting if the vote is already in the database
    const isOptimisticVote = hasVoted && !initialHasVoted;
    const currentTotalVotes = poll.totalVotes + (isOptimisticVote ? 1 : 0);

    const getPercentage = (votes: number) => {
        if (currentTotalVotes === 0) return 0;
        return Math.round((votes / currentTotalVotes) * 100);
    };

    const isClosed = poll.status === 'closed' || new Date(poll.endDate) < new Date();

    return (
        <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-xl shadow-slate-200/20 dark:shadow-none overflow-hidden h-full flex flex-col">
            <div className="p-8 md:p-10 flex-1 space-y-8">
                {/* Header */}
                <div className="space-y-4">
                    <div className="flex items-center justify-between">
                        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest ${poll.category === 'maintenance' ? 'bg-amber-50 text-amber-600 dark:bg-amber-500/10 dark:text-amber-400' :
                            poll.category === 'rules' ? 'bg-indigo-50 text-indigo-600 dark:bg-indigo-500/10 dark:text-indigo-400' :
                                'bg-blue-50 text-blue-600 dark:bg-blue-500/10 dark:text-blue-400'
                            }`}>
                            {poll.category === 'maintenance' ? 'Mantenimiento' :
                                poll.category === 'rules' ? 'Reglamento' : 'Comunidad'}
                        </span>
                        {isClosed && (
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest border border-slate-100 dark:border-slate-800 px-3 py-1.5 rounded-xl">
                                Cerrado
                            </span>
                        )}
                    </div>
                    <div className="space-y-2">
                        <h3 className="text-2xl font-black text-slate-900 dark:text-white leading-tight">{poll.title}</h3>
                        <p className="text-sm font-medium text-slate-400 leading-relaxed">{poll.description}</p>
                    </div>
                </div>

                {/* Options / Results */}
                <div className="space-y-4">
                    <AnimatePresence mode="wait">
                        {!hasVoted && !isClosed ? (
                            <motion.div
                                key="voting"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                                className="space-y-3"
                            >
                                {poll.options.map((option) => (
                                    <button
                                        key={option.id}
                                        onClick={() => setSelectedOption(option.id)}
                                        className={`w-full p-6 rounded-2xl border-2 transition-all flex items-center justify-between group ${selectedOption === option.id
                                            ? 'border-blue-600 bg-blue-50/50 dark:bg-blue-500/10'
                                            : 'border-slate-50 dark:border-slate-800 hover:border-slate-200 dark:hover:border-slate-700 bg-slate-50/50 dark:bg-slate-800/30'
                                            }`}
                                    >
                                        <span className={`font-bold transition-colors ${selectedOption === option.id ? 'text-blue-600 dark:text-blue-400' : 'text-slate-600 dark:text-slate-400'
                                            }`}>
                                            {option.text}
                                        </span>
                                        <div className={`h-6 w-6 rounded-full border-2 flex items-center justify-center transition-all ${selectedOption === option.id
                                            ? 'border-blue-600 bg-blue-600'
                                            : 'border-slate-200 dark:border-slate-700'
                                            }`}>
                                            {selectedOption === option.id && <CheckCircle2 className="h-4 w-4 text-white" />}
                                        </div>
                                    </button>
                                ))}
                            </motion.div>
                        ) : (
                            <motion.div
                                key="results"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="space-y-6"
                            >
                                {poll.options.map((option) => {
                                    const optimisticOptionVotes = option.votes + (isOptimisticVote && selectedOption === option.id ? 1 : 0);
                                    const percentage = getPercentage(optimisticOptionVotes);
                                    return (
                                        <div key={option.id} className="space-y-2">
                                            <div className="flex justify-between text-sm font-black uppercase tracking-widest text-slate-400 px-1">
                                                <span>{option.text}</span>
                                                <span className="text-slate-900 dark:text-white">{percentage}%</span>
                                            </div>
                                            <div className="h-4 w-full bg-slate-50 dark:bg-slate-800 rounded-full overflow-hidden">
                                                <motion.div
                                                    initial={{ width: 0 }}
                                                    animate={{ width: `${percentage}%` }}
                                                    transition={{ duration: 1, ease: "easeOut" }}
                                                    className={`h-full rounded-full ${poll.category === 'maintenance' ? 'bg-amber-500' :
                                                        poll.category === 'rules' ? 'bg-indigo-500' :
                                                            'bg-blue-500'
                                                        }`}
                                                />
                                            </div>
                                        </div>
                                    );
                                })}
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </div>

            {/* Footer */}
            <div className="p-8 bg-slate-50/50 dark:bg-slate-800/30 border-t border-slate-100 dark:border-slate-800 mt-auto">
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-3">
                        <div className="flex -space-x-2">
                            {[...Array(3)].map((_, i) => (
                                <div key={i} className="h-8 w-8 rounded-full border-2 border-white dark:border-slate-900 bg-slate-200 dark:bg-slate-700" />
                            ))}
                        </div>
                        <span className="text-xs font-bold text-slate-400">
                            {currentTotalVotes} votos registrados
                        </span>
                    </div>
                    <div className="flex items-center gap-2 text-xs font-bold text-slate-400">
                        <Clock className="h-4 w-4" />
                        <span>Faltan {Math.max(0, Math.ceil((new Date(poll.endDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)))} días</span>
                    </div>
                </div>

                {!hasVoted && !isClosed && (
                    <Button
                        onClick={handleVote}
                        disabled={!selectedOption}
                        className="w-full h-16 rounded-2xl bg-slate-900 dark:bg-slate-700 text-white font-black text-lg shadow-xl transition-all active:scale-[0.98] disabled:opacity-50"
                    >
                        <VoteIcon className="mr-2 h-5 w-5" />
                        Enviar mi Voto
                    </Button>
                )}

                {(hasVoted || isClosed) && (
                    <div className="text-center py-4 text-xs font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest">
                        {hasVoted ? "Voto Procesado con Éxito" : "Votación Finalizada"}
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Target, TrendingDown, CheckCircle2 } from "lucide-react";
import { motion } from "framer-motion";

interface SavingsGoalCardProps {
    currentConsumption: number;
    lastMonthConsumption: number;
}

export function SavingsGoalCard({ currentConsumption, lastMonthConsumption }: SavingsGoalCardProps) {
    const [goalPercentage, setGoalPercentage] = useState<number | null>(null);
    const [isGoalSet, setIsGoalSet] = useState(false);

    const handleSetGoal = (percentage: number) => {
        setGoalPercentage(percentage);
        setIsGoalSet(true);
    };

    const targetConsumption = goalPercentage
        ? lastMonthConsumption * (1 - goalPercentage / 100)
        : lastMonthConsumption;

    const progress = Math.min(100, (currentConsumption / targetConsumption) * 100);
    const isOnTrack = currentConsumption <= targetConsumption;

    return (
        <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white relative overflow-hidden">
            {/* Background */}
            <div className="absolute top-0 right-0 p-8 opacity-10">
                <Target className="h-40 w-40 text-blue-500" />
            </div>

            <div className="relative z-10 space-y-6">
                <div className="flex items-center gap-4">
                    <div className="p-3 bg-blue-500/20 rounded-2xl text-blue-400">
                        <Target className="h-6 w-6" />
                    </div>
                    <div>
                        <h3 className="text-xl font-black text-white">Meta de Ahorro</h3>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Desafío Mensual</p>
                    </div>
                </div>

                {!isGoalSet ? (
                    <div className="space-y-4">
                        <p className="text-sm font-medium text-slate-300">
                            Propóngase una meta de reducción respecto al mes anterior ({lastMonthConsumption} m³).
                        </p>
                        <div className="grid grid-cols-3 gap-3">
                            {[5, 10, 15].map((percent) => (
                                <button
                                    key={percent}
                                    onClick={() => handleSetGoal(percent)}
                                    className="py-3 px-4 rounded-xl border border-slate-700 hover:bg-blue-600 hover:border-blue-500 transition-all text-center group"
                                >
                                    <span className="block text-2xl font-black text-white group-hover:scale-110 transition-transform">{percent}%</span>
                                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest group-hover:text-blue-200">Menos</span>
                                </button>
                            ))}
                        </div>
                    </div>
                ) : (
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="space-y-6"
                    >
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Meta de Consumo</p>
                                <p className="text-2xl font-black text-white flex items-center gap-2">
                                    {targetConsumption.toFixed(1)} m³
                                    <span className="text-xs font-bold text-emerald-400 px-2 py-1 bg-emerald-500/20 rounded-lg">
                                        -{goalPercentage}%
                                    </span>
                                </p>
                            </div>
                            <button
                                onClick={() => setIsGoalSet(false)}
                                className="text-xs font-bold text-slate-500 hover:text-white transition-colors"
                            >
                                Cambiar
                            </button>
                        </div>

                        <div className="space-y-2">
                            <div className="flex justify-between text-xs font-bold text-slate-400 uppercase tracking-widest">
                                <span>Progreso</span>
                                <span>{progress.toFixed(0)}%</span>
                            </div>
                            <div className="h-4 bg-slate-800 rounded-full overflow-hidden">
                                <motion.div
                                    initial={{ width: 0 }}
                                    animate={{ width: `${progress}%` }}
                                    className={`h-full rounded-full ${progress > 100 ? 'bg-red-500' :
                                            progress > 80 ? 'bg-amber-500' : 'bg-emerald-500'
                                        }`}
                                />
                            </div>
                            <p className="text-xs font-medium text-slate-400 pt-1">
                                {progress > 100
                                    ? "Has excedido tu meta mensual."
                                    : `Llevas ${currentConsumption} m³ consumidos. ¡Vas bien!`}
                            </p>
                        </div>

                        {isOnTrack && (
                            <div className="flex items-center gap-3 p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl">
                                <CheckCircle2 className="h-5 w-5 text-emerald-500 shrink-0" />
                                <p className="text-xs font-bold text-emerald-400">
                                    Estás en camino a cumplir tu meta. ¡Sigue así!
                                </p>
                            </div>
                        )}
                    </motion.div>
                )}
            </div>
        </div>
    );
}

import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid,
    Tooltip, ResponsiveContainer, Cell, AreaChart, Area
} from 'recharts';
import { motion } from 'framer-motion';
import { Droplets, TrendingDown, AlertTriangle, Info } from 'lucide-react';
import { ConsumptionMetric } from '@/lib/types';

interface WaterConsumptionChartProps {
    data: ConsumptionMetric[];
}

export function WaterConsumptionChart({ data }: WaterConsumptionChartProps) {
    // Si no hay datos, mostrar estado vacío
    if (!data || data.length === 0) {
        return (
            <div className="p-8 bg-slate-50 dark:bg-slate-800/50 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 text-center">
                <p className="text-slate-500">No hay datos de consumo registrados aún.</p>
            </div>
        );
    }


    // Calculate efficiency
    const currentMonth = data[data.length - 1];
    const isEfficient = currentMonth.personal < currentMonth.average;
    const diffPercentage = Math.round(Math.abs((currentMonth.personal - currentMonth.average) / currentMonth.average) * 100);

    return (
        <div className="space-y-8">
            {/* Efficiency Highlight Card */}
            <div className={`p-8 rounded-[2.5rem] border transition-all ${isEfficient
                ? 'bg-emerald-50/50 dark:bg-emerald-500/5 border-emerald-100 dark:border-emerald-500/20'
                : 'bg-amber-50/50 dark:bg-amber-500/5 border-amber-100 dark:border-amber-500/20'
                }`}>
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center gap-6">
                        <div className={`p-5 rounded-2xl ${isEfficient ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'
                            }`}>
                            {isEfficient ? <TrendingDown className="h-8 w-8" /> : <AlertTriangle className="h-8 w-8" />}
                        </div>
                        <div className="space-y-1">
                            <h3 className="text-2xl font-black text-slate-900 dark:text-white leading-tight">
                                {isEfficient ? 'Consumo Eficiente' : 'Consumo Elevado'}
                            </h3>
                            <p className="text-sm font-medium text-slate-500">
                                {isEfficient
                                    ? `Estás consumiendo un ${diffPercentage}% menos que el promedio de la torre.`
                                    : `Estás consumiendo un ${diffPercentage}% más que el promedio de la torre.`}
                            </p>
                        </div>
                    </div>
                    <div className="px-6 py-4 bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Tu Consumo Ene</p>
                        <p className="text-2xl font-black text-slate-900 dark:text-white">{currentMonth.personal} m³</p>
                    </div>
                </div>
            </div>

            {/* Main Chart Container */}
            <div className="bg-white dark:bg-slate-900 p-8 md:p-12 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-xl shadow-slate-200/20 dark:shadow-none space-y-10">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-blue-50 dark:bg-blue-500/10 rounded-2xl text-blue-600 dark:text-blue-400">
                            <Droplets className="h-6 w-6" />
                        </div>
                        <h2 className="text-2xl font-black text-slate-900 dark:text-white">Tendencia Histórica</h2>
                    </div>

                    <div className="flex items-center gap-6">
                        <div className="flex items-center gap-2">
                            <div className="h-3 w-3 rounded-full bg-blue-500" />
                            <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Personal</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="h-3 w-3 rounded-full bg-slate-200 dark:bg-slate-700" />
                            <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Promedio Torre</span>
                        </div>
                    </div>
                </div>

                <div className="h-[350px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={data} margin={{ top: 20, right: 0, left: -20, bottom: 0 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                            <XAxis
                                dataKey="month"
                                axisLine={false}
                                tickLine={false}
                                tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 700 }}
                                dy={15}
                            />
                            <YAxis
                                axisLine={false}
                                tickLine={false}
                                tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 700 }}
                            />
                            <Tooltip
                                cursor={{ fill: 'transparent' }}
                                content={({ active, payload }) => {
                                    if (active && payload && payload.length) {
                                        return (
                                            <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-2xl border border-white/10 space-y-4">
                                                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{payload[0].payload.month}</p>
                                                <div className="space-y-2">
                                                    <div className="flex items-center justify-between gap-8">
                                                        <span className="text-xs font-bold text-slate-400">Personal</span>
                                                        <span className="text-lg font-black text-blue-400">{payload[0].value} m³</span>
                                                    </div>
                                                    <div className="flex items-center justify-between gap-8">
                                                        <span className="text-xs font-bold text-slate-400">Promedio</span>
                                                        <span className="text-lg font-black text-white">{payload[1].value} m³</span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    }
                                    return null;
                                }}
                            />
                            <Bar dataKey="personal" radius={[8, 8, 0, 0]} barSize={40}>
                                {data.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={index === data.length - 1 ? '#3b82f6' : '#94a3b833'} />
                                ))}
                            </Bar>
                            <Bar dataKey="average" fill="#cbd5e144" radius={[8, 8, 0, 0]} barSize={40} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>

                {/* Legend / Info */}
                <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-2xl flex gap-4 items-start border border-slate-100 dark:border-slate-700">
                    <Info className="h-5 w-5 text-slate-400 shrink-0 mt-0.5" />
                    <p className="text-xs font-medium text-slate-500 leading-relaxed">
                        Los consumos se calculan en base a la lectura de su remarcador individual. El promedio de la torre incluye todas las unidades de su misma tipología (mismos dormitorios/baños).
                    </p>
                </div>
            </div>
        </div>
    );
}

