"use client";

import { motion, AnimatePresence } from "framer-motion";
import { usePathname } from "next/navigation";

interface PageTransitionProps {
    children: React.ReactNode;
}

// Page transition wrapper component
export function PageTransition({ children }: PageTransitionProps) {
    const pathname = usePathname();

    return (
        <AnimatePresence mode="wait">
            <motion.div
                key={pathname}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{
                    duration: 0.3,
                    ease: [0.4, 0, 0.2, 1]
                }}
            >
                {children}
            </motion.div>
        </AnimatePresence>
    );
}

// Staggered list animation for cards/items
export function StaggerContainer({ children, className }: { children: React.ReactNode; className?: string }) {
    return (
        <motion.div
            className={className}
            initial="hidden"
            animate="visible"
            variants={{
                hidden: { opacity: 0 },
                visible: {
                    opacity: 1,
                    transition: {
                        staggerChildren: 0.1
                    }
                }
            }}
        >
            {children}
        </motion.div>
    );
}

export function StaggerItem({ children, className }: { children: React.ReactNode; className?: string }) {
    return (
        <motion.div
            className={className}
            variants={{
                hidden: { opacity: 0, y: 20 },
                visible: {
                    opacity: 1,
                    y: 0,
                    transition: {
                        duration: 0.4,
                        ease: [0.4, 0, 0.2, 1]
                    }
                }
            }}
        >
            {children}
        </motion.div>
    );
}

// Fade in animation
export function FadeIn({
    children,
    delay = 0,
    duration = 0.5,
    className
}: {
    children: React.ReactNode;
    delay?: number;
    duration?: number;
    className?: string;
}) {
    return (
        <motion.div
            className={className}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay, duration, ease: "easeOut" }}
        >
            {children}
        </motion.div>
    );
}

// Slide in from direction
export function SlideIn({
    children,
    direction = "up",
    delay = 0,
    className
}: {
    children: React.ReactNode;
    direction?: "up" | "down" | "left" | "right";
    delay?: number;
    className?: string;
}) {
    const directionOffset = {
        up: { y: 30 },
        down: { y: -30 },
        left: { x: 30 },
        right: { x: -30 }
    };

    return (
        <motion.div
            className={className}
            initial={{ opacity: 0, ...directionOffset[direction] }}
            animate={{ opacity: 1, x: 0, y: 0 }}
            transition={{ delay, duration: 0.5, ease: [0.4, 0, 0.2, 1] }}
        >
            {children}
        </motion.div>
    );
}

// Scale animation for interactive elements
export function ScaleOnHover({
    children,
    scale = 1.02,
    className
}: {
    children: React.ReactNode;
    scale?: number;
    className?: string;
}) {
    return (
        <motion.div
            className={className}
            whileHover={{ scale }}
            whileTap={{ scale: 0.98 }}
            transition={{ duration: 0.2 }}
        >
            {children}
        </motion.div>
    );
}

// Animated counter for stats
export function AnimatedNumber({
    value,
    duration = 1,
    prefix = "",
    suffix = ""
}: {
    value: number;
    duration?: number;
    prefix?: string;
    suffix?: string;
}) {
    return (
        <motion.span
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
        >
            <motion.span
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
            >
                {prefix}
                <motion.span
                    key={value}
                    initial={{ y: 10, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ duration: 0.3 }}
                >
                    {value.toLocaleString('es-CL')}
                </motion.span>
                {suffix}
            </motion.span>
        </motion.span>
    );
}

// Pulse animation for notifications/alerts
export function Pulse({ children, className }: { children: React.ReactNode; className?: string }) {
    return (
        <motion.div
            className={className}
            animate={{
                scale: [1, 1.05, 1],
            }}
            transition={{
                duration: 2,
                repeat: Infinity,
                repeatType: "reverse"
            }}
        >
            {children}
        </motion.div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { getApiUrl, API_BASE_URL } from "@/lib/config";

export function DebugStats() {
    const [stats, setStats] = useState<any>(null);
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        // Toggle with Alt+Shift+D
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.altKey && e.shiftKey && e.key === 'D') {
                setIsVisible(v => !v);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    useEffect(() => {
        if (!isVisible) return;

        const checkApis = async () => {
            const results: any = {
                env: {
                    NEXT_PUBLIC_SITE_URL: process.env.NEXT_PUBLIC_SITE_URL || "not set",
                    API_BASE_URL: API_BASE_URL,
                    window_origin: typeof window !== 'undefined' ? window.origin : 'N/A',
                },
                endpoints: {}
            };

            const apis = ['/api/coco', '/api/payments/create-haulmer-link'];

            for (const path of apis) {
                const url = getApiUrl(path);
                try {
                    const start = performance.now();
                    const res = await fetch(url, { 
                        method: 'POST', 
                        body: JSON.stringify({ test: true }),
                        headers: { 'Content-Type': 'application/json' }
                    });
                    const end = performance.now();
                    results.endpoints[path] = {
                        status: res.status,
                        ok: res.ok,
                        time: `${Math.round(end - start)}ms`,
                        url_used: url
                    };
                } catch (e: any) {
                    results.endpoints[path] = {
                        error: e.message,
                        url_used: url
                    };
                }
            }
            setStats(results);
        };

        checkApis();
    }, [isVisible]);

    if (!isVisible) return null;

    return (
        <div className="fixed top-20 right-4 z-[9999] w-96 bg-black/90 text-green-400 p-4 rounded-2xl font-mono text-[10px] shadow-2xl border border-green-500/30 overflow-auto max-h-[80vh]">
            <div className="flex justify-between items-center mb-4 border-b border-green-500/20 pb-2">
                <span className="font-bold">SYSTEM DIAGNOSTICS (Alt+Shift+D)</span>
                <button onClick={() => setIsVisible(false)} className="text-red-500">CLOSE</button>
            </div>

            <pre>{JSON.stringify(stats, null, 2)}</pre>

            <div className="mt-4 p-2 bg-green-500/10 rounded">
                <p className="text-white font-bold">Performance Tips:</p>
                <ul className="list-disc list-inside space-y-1 mt-1 opacity-80">
                    <li>Using absolute API URLs: {stats?.endpoints?.['/api/coco']?.url_used?.startsWith('http') ? 'YES' : 'NO'}</li>
                    <li>Environment: {process.env.NODE_ENV}</li>
                </ul>
            </div>
        </div>
    );
}

"use client";

import React, { Component, ErrorInfo, ReactNode } from "react";
import { Shield, AlertTriangle, RefreshCw } from "lucide-react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  name?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error(`[ErrorBoundary: ${this.props.name || 'Unknon'}]`, error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      if (this.props.fallback) return this.props.fallback;

      return (
        <div className="p-8 my-4 rounded-3xl bg-rose-50 dark:bg-rose-950/20 border border-rose-100 dark:border-rose-900/30 text-center space-y-4">
          <div className="mx-auto w-12 h-12 rounded-xl bg-rose-500 shadow-lg shadow-rose-500/30 flex items-center justify-center">
            <AlertTriangle className="h-6 w-6 text-white" />
          </div>
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">Lo sentimos, hubo un error en este módulo</h2>
          <p className="text-sm text-slate-500 dark:text-slate-400 max-w-sm mx-auto">
            {this.props.name ? `El módulo "${this.props.name}"` : 'Esta sección'} no pudo cargarse correctamente.
          </p>
          <button
            onClick={() => this.setState({ hasError: false, error: null })}
            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-slate-900 dark:bg-white text-white dark:text-slate-900 text-sm font-bold shadow-sm"
          >
            <RefreshCw className="h-4 w-4" />
            Intentar de nuevo
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

