"use client";

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from './types';
import type { User as SupabaseUser, Session } from '@supabase/supabase-js';
import { supabase } from '@/lib/supabase';

// ============================================
// Unified Auth Context
// Supports both demo mode (login by role) and Supabase auth
// ============================================

interface AuthContextType {
    // Common
    user: User | null;
    loading: boolean;
    logout: () => Promise<void>;

    // Supabase mode
    supabaseUser: SupabaseUser | null;
    session: Session | null;
    signIn: (email: string, password: string) => Promise<{ error: Error | null }>;
    signUp: (email: string, password: string, userData: Record<string, any>) => Promise<{ error: Error | null }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
    // Demo state
    const [user, setUser] = useState<User | null>(null);

    // Supabase state
    const [supabaseUser, setSupabaseUser] = useState<SupabaseUser | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [loading, setLoading] = useState(true);

    // Initialize Supabase auth listener
    useEffect(() => {
        // Check if Supabase is configured
        const isSupabaseConfigured = process.env.NEXT_PUBLIC_SUPABASE_URL && process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
        
        if (!isSupabaseConfigured) {
            console.log("Supabase not configured - running in demo mode");
            setLoading(false);
            return;
        }

        // Check active session safely
        const checkSessionSafe = async () => {
            setLoading(true);
            const controller = new AbortController();
            const timeoutId = setTimeout(() => {
                setLoading(false);
                console.warn("Auth session check timed out");
            }, 8000);

            try {
                // Add a safety timeout for the session check to prevent hanging the app on slow networks
                const sessionPromise = supabase.auth.getSession();
                const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("Auth timeout")), 5000));
                
                const { data: { session }, error } = await Promise.race([sessionPromise, timeoutPromise]) as any;
                if (error) throw error;

                setSession(session);
                setSupabaseUser(session?.user ?? null);
                if (session?.user) {
                    await fetchUserProfile(session.user); // Await profile fetch
                } else {
                    setLoading(false);
                }
            } catch (err) {
                console.warn("Auth session check failed (likely expired token or timeout):", err);

                // Self-healing: aggressively clear corrupted auth tokens from localStorage
                if (typeof window !== 'undefined') {
                    try {
                        for (const key of Object.keys(localStorage)) {
                            if (key.startsWith('sb-') && key.endsWith('-auth-token')) {
                                localStorage.removeItem(key);
                            }
                        }
                    } catch (e) {
                        // ignore clear errors
                    }
                }

                setSession(null);
                setSupabaseUser(null);
                setLoading(false);
            } finally {
                clearTimeout(timeoutId);
                setLoading(false);
            }
        };
        checkSessionSafe();

        // Listen for changes
        const {
            data: { subscription },
        } = supabase.auth.onAuthStateChange((_event: any, session: any) => {
            setSession(session);
            setSupabaseUser(session?.user ?? null);

            if (session?.user) {
                fetchUserProfile(session.user);
            } else {
                // Clear user if logged out
                setUser(null);
                setLoading(false);
            }
        });

        return () => subscription.unsubscribe();
    }, []);

    // Fetch real profile from public.profiles table (Source of Truth)
    const fetchUserProfile = async (sbUser: SupabaseUser) => {
        try {
            const { data: profile, error } = await supabase
                .from('profiles')
                .select('*')
                .eq('id', sbUser.id)
                .single();

            if (error) {
                console.error("Error fetching profile:", error);
                // Fallback to metadata if profile fails
                mapSupabaseUserFromMetadata(sbUser);
            } else if (profile) {
                // Extract a readable display name from email as last resort
                const emailFirstPart = sbUser.email?.split('@')[0]?.split('.')?.[0];
                const displayName = profile.name
                    || (emailFirstPart ? emailFirstPart.charAt(0).toUpperCase() + emailFirstPart.slice(1) : null)
                    || 'Usuario';

                // Map from DB profile
                setUser({
                    id: sbUser.id,
                    name: displayName,
                    email: sbUser.email || '',
                    role: profile.role || 'resident',
                    unitId: undefined,
                    photo: profile.avatar_url
                });

                // Fetch unit if exists
                fetchUnitForUser(sbUser.id);
            }
        } catch (err) {
            console.error(err);
            mapSupabaseUserFromMetadata(sbUser);
        } finally {
            setLoading(false);
        }
    };

    // Helper to fetch unit
    const fetchUnitForUser = async (userId: string) => {
        try {
            const { data: unit, error } = await supabase
                .from('units')
                .select('id, number, tower')
                .eq('owner_id', userId)
                .maybeSingle();

            if (unit && !error) {
                setUser(prev => prev ? ({ ...prev, unitId: unit.id, unitName: unit.number ? `Depto ${unit.number}` : undefined }) : null);
            }
        } catch (err) {
            console.warn("Could not fetch unit for user (ignoring):", err);
        }
    };

    // Fallback Helper
    const mapSupabaseUserFromMetadata = (sbUser: SupabaseUser) => {
        setUser({
            id: sbUser.id,
            name: sbUser.user_metadata?.name || sbUser.email || 'Usuario',
            email: sbUser.email || '',
            role: sbUser.user_metadata?.role || 'resident',
            unitId: sbUser.user_metadata?.unit_id,
            unitName: sbUser.user_metadata?.unit_number ? `Depto ${sbUser.user_metadata.unit_number}` : undefined,
        });
    };
    // Supabase sign in
    const signIn = async (email: string, password: string) => {
        try {
            const { error } = await supabase.auth.signInWithPassword({ email, password });
            return { error };
        } catch (error) {
            return { error: error as Error };
        }
    };

    // Supabase sign up
    const signUp = async (email: string, password: string, userData: Record<string, any>) => {
        try {
            // Determine current origin for email redirection
            const origin = typeof window !== 'undefined' ? window.location.origin : 'https://comunidadconnect.vercel.app';
            
            if (!process.env.NEXT_PUBLIC_SUPABASE_URL) {
                console.error("Supabase not configured. Signup will fail.");
                return { error: new Error("Sistema configurado en modo DEMO. El registro real no está disponible.") };
            }

            const { data, error } = await supabase.auth.signUp({
                email,
                password,
                options: {
                    data: userData,
                    emailRedirectTo: `${origin}/login`,
                },
            });
            if (error) return { error };
            return { error: null };
        } catch (error: any) {
            return { error };
        }
    };

    // Logout (handles both modes)
    const logout = async () => {
        setUser(null);
        setSupabaseUser(null);
        setSession(null);
        await supabase.auth.signOut();
    };

    return (
        <AuthContext.Provider value={{
            user,
            loading,
            logout,
            supabaseUser,
            session,
            signIn,
            signUp,
        }}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}

import { supabase } from '../supabase';

interface PaymentPayload {
    amount: number;
    description: string;
    reference: string; // ID interno nuestro (e.g., deudo ID o carrito ID)
    client: {
        email: string;
        name: string;
    };
    returnUrl: string; // URL a donde vuelve el usuario despues de pagar
}

/**
 * Servicio para integrar el Gateway de Pagos de Haulmer.
 * Documentación Base: Endpoint POST /v1/checkout/payment
 */
export const HaulmerService = {
    apiKey: process.env.HAULMER_API_KEY || '',
    apiUrl: 'https://pay.haulmer.com/v1/checkout/payment',

    /**
     * Crea un intento de pago (Payment Link) en Haulmer.
     * Retorna la URL a donde debemos redirigir al usuario para completar el pago.
     */
    async createPaymentLink(payload: PaymentPayload): Promise<{ token: string; url: string }> {
        if (!this.apiKey) {
            console.warn("⚠️ HAULMER_API_KEY no detectada. Usando MOCK_URL para desarrollo local.");
            return {
                token: "mock_token_123",
                url: `/mock-payment?ref=${payload.reference}&amount=${payload.amount}`
            };
        }

        const body = {
            amount: payload.amount,
            description: payload.description,
            currency: 'CLP',
            external_id: payload.reference, // ID para trackear en nuestro webhook
            client: {
                name: payload.client.name,
                email: payload.client.email
            },
            urls: {
                return_url: payload.returnUrl
            }
        };

        try {
            const response = await fetch(this.apiUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'apikey': this.apiKey
                },
                body: JSON.stringify(body)
            });

            if (!response.ok) {
                const errorData = await response.json();
                console.error("Haulmer API Error:", errorData);
                throw new Error(errorData.message || "Error al generar cobro en Haulmer");
            }

            const data = await response.json();

            // Haulmer retorna tipícamente el redireccionamiento (ej. data.token, data.payment_url)
            // Ajustar los campos exactos según la documentación V1 de Haulmer en producción real
            return {
                token: data.token || data.id,
                url: data.url || `https://pay.haulmer.com/checkout?token=${data.token}`
            };

        } catch (error) {
            console.error("HaulmerService.createPaymentLink() Failed:", error);
            throw error;
        }
    }
};

import { supabase } from '../supabase';

export interface DbNotification {
    id: string;
    user_id: string;
    type: 'info' | 'success' | 'warning' | 'alert';
    category: string;
    title: string;
    body: string;
    link?: string;
    read: boolean;
    created_at: string;
}

export interface CreateNotificationPayload {
    user_id: string;
    type: 'info' | 'success' | 'warning' | 'alert';
    category?: string;
    title: string;
    body: string;
    link?: string;
}

export const NotificationService = {
    // Get all notifications for the current user (latest 30)
    async getNotifications(userId: string, limit = 30): Promise<DbNotification[]> {
        const { data, error } = await supabase
            .from('notifications')
            .select('*')
            .eq('user_id', userId)
            .order('created_at', { ascending: false })
            .limit(limit);

        if (error) throw error;
        return data || [];
    },

    // Mark a single notification as read
    async markAsRead(notificationId: string): Promise<void> {
        const { error } = await supabase
            .from('notifications')
            .update({ read: true })
            .eq('id', notificationId);
        if (error) throw error;
    },

    // Mark all as read for the user
    async markAllAsRead(userId: string): Promise<void> {
        const { error } = await supabase
            .from('notifications')
            .update({ read: true })
            .eq('user_id', userId)
            .eq('read', false);
        if (error) throw error;
    },

    // Delete a single notification
    async deleteNotification(notificationId: string): Promise<void> {
        const { error } = await supabase
            .from('notifications')
            .delete()
            .eq('id', notificationId);
        if (error) throw error;
    },

    // Delete all notifications for user
    async deleteAll(userId: string): Promise<void> {
        const { error } = await supabase
            .from('notifications')
            .delete()
            .eq('user_id', userId);
        if (error) throw error;
    },

    // Create a notification (called by other services)
    async create(payload: CreateNotificationPayload): Promise<DbNotification | null> {
        const { data, error } = await supabase
            .from('notifications')
            .insert({
                ...payload,
                category: payload.category || payload.type
            })
            .select()
            .single();
        if (error) {
            console.error('[NotificationService.create] Error:', error);
            return null;
        }
        return data;
    },

    // Subscribe to new notifications in real time for a given user
    subscribeToNotifications(userId: string, onNew: (n: DbNotification) => void) {
        const channel = supabase.channel(`notifications_${userId}`)
            .on(
                'postgres_changes',
                {
                    event: 'INSERT',
                    schema: 'public',
                    table: 'notifications',
                    filter: `user_id=eq.${userId}`
                },
                (payload: any) => {
                    onNew(payload.new as DbNotification);
                }
            )
            .subscribe();
        return channel;
    }
};

