// ==========================================
// Polls / Voting Service
// ==========================================
export const PollService = {
    async getAll() {
        const { data, error } = await supabase
            .from('polls')
            .select(`
        *,
        poll_options (*)
      `)
            .order('created_at', { ascending: false });

        if (error) throw error;
        return data;
    },

    async getById(pollId: string) {
        const { data, error } = await supabase
            .from('polls')
            .select(`
        *,
        poll_options (*)
      `)
            .eq('id', pollId)
            .single();

        if (error) throw error;
        return data;
    },

    async create(poll: {
        title: string;
        description?: string;
        category: string;
        end_date: string;
        created_by: string;
    }, options: string[]) {
        // Create poll
        const { data: pollData, error: pollError } = await supabase
            .from('polls')
            .insert(poll)
            .select()
            .single();

        if (pollError) throw pollError;

        // Create options
        const optionInserts = options.map((text: string, idx: number) => ({
            poll_id: pollData.id,
            text,
            display_order: idx,
        }));

        const { error: optionsError } = await supabase
            .from('poll_options')
            .insert(optionInserts);

        if (optionsError) throw optionsError;

        return pollData;
    },

    async vote(pollId: string, optionId: string, userId: string) {
        // Insert vote
        const { error: voteError } = await supabase
            .from('poll_votes')
            .insert({
                poll_id: pollId,
                option_id: optionId,
                user_id: userId,
            });

        if (voteError) throw voteError;

        // Increment option vote count
        const { error: updateError } = await supabase.rpc('increment_vote', {
            option_id: optionId,
        });

        // Fallback: manual increment if RPC doesn't exist
        if (updateError) {
            const { data: option } = await supabase
                .from('poll_options')
                .select('votes')
                .eq('id', optionId)
                .single();

            if (option) {
                await supabase
                    .from('poll_options')
                    .update({ votes: (option.votes || 0) + 1 })
                    .eq('id', optionId);
            }
        }
    },

    async getUserVote(pollId: string, userId: string) {
        const { data, error } = await supabase
            .from('poll_votes')
            .select('option_id')
            .eq('poll_id', pollId)
            .eq('user_id', userId)
            .maybeSingle();

        if (error) throw error;
        return data?.option_id || null;
    },

    async closePoll(pollId: string) {
        const { error } = await supabase
            .from('polls')
            .update({ status: 'closed' })
            .eq('id', pollId);

        if (error) throw error;
    },
};

